INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C1','soc',3,1,'u1',1,'여러 장소 — 장소 = 사람들이 생활하며 이용하는, 찾아갈 수 있는 곳(기쁨·어제는 장소가 아님) · 자연이 만든 장소(산·강)와 사람이 만든 장소(학교·시장) · 장소마다 모습과 하는 일이 달라 필요한 일에 맞는 곳을 찾아감',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C2','soc',3,1,'u1',2,'장소 분류하기 — 분류 = 비슷한 특징끼리 무리지어 나눔 · 먼저 무엇을 보고 나눌지 기준을 정함 · 누가 만들었나(자연/사람) · 하는 일(배우는 곳/사고파는 곳/노는 곳) · 기준이 바뀌면 무리도 달라짐 · 자주 가는 곳처럼 사람마다 다른 기준도 있음',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C3','soc',3,1,'u1',3,'장소에서의 경험과 느낌 — 경험 = 장소에서 겪은 일 · 느낌 = 그때 든 마음 · 경험과 느낌은 짝 · 같은 장소라도 사람마다 · 때마다 느낌이 다름(맞고 그름이 아님) · 장소 카드 = 장소 이름 · 경험 · 느낌 · 친구의 다른 느낌을 존중하며 들음',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C4','soc',3,1,'u1',4,'장소를 표현하고 소개하기 — 그림 · 신문 · 노래 · 모형처럼 여러 방법으로 표현 · 그림 = 모습과 느낌을 색과 그림으로 · 마을 신문 = 장소 사진 · 소개 글 · 소식 · 작품을 소개하고 친구 작품의 좋은 점을 찾아 말함 · 촬영 장소 섭외자',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C5','soc',3,1,'u1',5,'공유 앱으로 알리기 — 작품을 사진으로 찍어 올리면 교실 밖 · 멀리 있는 친구와도 함께 봄 · 고운 말 댓글로 좋은 점 칭찬 · 예의 바르게 묻기 · 흉보지 않기 · 남의 정보를 함부로 올리지 않기 · 고운 댓글에는 고마움',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C6','soc',3,1,'u1',6,'그림일기와 모형으로 정리하기 — 그림일기에 장소 · 경험 · 느낌을 그림과 글로 함께 담음 · 우리 동네를 입체 모형으로 정성껏 만들고 친구 작품의 좋은 점을 칭찬 · 소단원 정리(장소 · 느낌 · 표현 · 공유)',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C7','soc',3,1,'u1',7,'생활에 도움을 주는 장소 — 여러 사람이 함께 이용하며 생활을 편리하고 안전하게 도와주는 곳(공공시설) · 병원 = 건강 · 소방서 = 불과 위험 · 우체국 = 편지와 물건 · 경찰서 = 위험을 막고 질서 · 곳마다 도움이 다르고 없으면 불편',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C8','soc',3,1,'u1',8,'도움을 주는 장소에서 하는 일 — 하는 일에 따라 안전(소방서 · 경찰서) · 건강(병원 · 보건소) · 배움(도서관)으로 묶음 · 우체국처럼 새 기준(생활을 편리하게)이 필요한 곳도 있음 · 같은 장소도 기준에 따라 다른 무리',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C9','soc',3,1,'u1',9,'디지털 영상 지도로 장소 찾기 — 디지털 영상 지도 = 위성 · 항공 사진으로 실제 모습을 보여 주는 지도 · 검색창에 이름을 넣어 위치를 찾음 · 이름과 기호로 어떤 장소인지 · 위치 · 가는 길 · 주변 장소를 앎(맛 · 냄새는 알 수 없음)',ARRAY['[4사01-01] 우리가 사는 곳의 여러 장소에 대한 경험과 느낌을 표현하고, 생활에 도움을 주는 장소를 탐색한다(차시 머리 표기 · 문구 초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C10','soc',3,1,'u1',10,'디지털 영상 지도의 기능 — 검색(이름으로 위치) · 확대 ＋(크고 자세히) · 축소 －(넓게) · 위성 보기(실제 모습) · 길찾기(출발과 도착을 정해 가는 길) · 찾는 차례 = 검색 → 크기 맞추기 → 길찾기',ARRAY['[4사01-02] 디지털 영상 지도로 장소를 찾고, 살기 좋은 곳의 조건과 더 살기 좋게 만드는 방안을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C11','soc',3,1,'u1',11,'살기 좋은 곳의 조건 — 안전(밝은 가로등 · 횡단보도) · 환경(깨끗함 · 나무와 공원) · 편리(가게 · 병원 · 도서관이 가까움) · 어울림(이웃이 인사하고 도움) · 여러 조건을 함께 갖춘 곳 · 우리 동네를 조건에 비추어 좋은 점과 고칠 점을 찾음',ARRAY['[4사01-02] 디지털 영상 지도로 장소를 찾고, 살기 좋은 곳의 조건과 더 살기 좋게 만드는 방안을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u1-C12','soc',3,1,'u1',12,'더 살기 좋은 곳으로 만드는 방안 — 고칠 점 찾기 → 알맞은 방안 정하기 → 함께 실천하기 · 내가 바로 할 일(쓰레기 안 버리기 · 인사)과 함께 할 일(의견 내고 의논) · 어린이 보호구역에서는 차가 천천히',ARRAY['[4사01-02] 디지털 영상 지도로 장소를 찾고, 살기 좋은 곳의 조건과 더 살기 좋게 만드는 방안을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X01','soc',3,'u1',ARRAY['SO3-1-u1-C1']::text[],'기쁨 · 어제 · 빠르기처럼 찾아갈 수 없는 것을 장소로 여긴다','찾아갈 수 있는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X02','soc',3,'u1',ARRAY['SO3-1-u1-C1']::text[],'장소는 모두 똑같거나 사람들의 생활과 상관없다고 여긴다','장소마다 모습과 하는 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X03','soc',3,'u1',ARRAY['SO3-1-u1-C1','SO3-1-u1-C2']::text[],'산 · 강처럼 자연이 만든 곳은 장소가 아니라고 여기거나 자연이 만든 곳과 사람이 만든 곳을 바꾸어 가른다','누가 만들었나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X04','soc',3,'u1',ARRAY['SO3-1-u1-C1','SO3-1-u1-C7','SO3-1-u1-C8']::text[],'장소와 그곳에서 하는 일을 엇갈리게 짝짓는다(시장에서 책 빌리기)','그곳에서 무엇을 하나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X05','soc',3,'u1',ARRAY['SO3-1-u1-C2','SO3-1-u1-C8']::text[],'기준을 정하지 않고 아무렇게나 나누거나 분류의 뜻을 모른다','기준부터 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X06','soc',3,'u1',ARRAY['SO3-1-u1-C2','SO3-1-u1-C8']::text[],'기준이 바뀌어도 무리는 그대로이고 한 장소는 늘 한 무리에만 든다고 여긴다','기준이 바뀌면 무리도 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X07','soc',3,'u1',ARRAY['SO3-1-u1-C2']::text[],'자주 가는 곳처럼 사람마다 다른 기준으로 나눈 무리도 모두 같아야 한다고 여긴다','사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X08','soc',3,'u1',ARRAY['SO3-1-u1-C3','SO3-1-u1-C6']::text[],'경험(겪은 일)과 느낌(그때의 마음)을 바꾸어 안다','겪은 일 · 그때의 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X09','soc',3,'u1',ARRAY['SO3-1-u1-C3','SO3-1-u1-C6']::text[],'같은 장소에서 느낌이 서로 다르면 한 사람이 잘못 느꼈다고 여긴다','느낌엔 정답이 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X10','soc',3,'u1',ARRAY['SO3-1-u1-C3','SO3-1-u1-C6']::text[],'장소 카드 · 그림일기에 장소 · 경험 · 느낌과 상관없는 것(친구 키 · 몸무게)을 담는다','장소 · 경험 · 느낌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X11','soc',3,'u1',ARRAY['SO3-1-u1-C3','SO3-1-u1-C4','SO3-1-u1-C6']::text[],'친구의 다른 느낌이나 작품을 놀리거나 무시한다','좋은 점을 찾아 존중해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X12','soc',3,'u1',ARRAY['SO3-1-u1-C4','SO3-1-u1-C6']::text[],'장소를 표현하는 방법은 한 가지뿐이라고 여기거나 표현이 아닌 것(베끼기)을 표현으로 여긴다','그림 · 신문 · 노래 · 모형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X13','soc',3,'u1',ARRAY['SO3-1-u1-C4']::text[],'마을 신문에 담을 것(사진 · 소개 글 · 소식)을 모르고 상관없는 것을 담는다','사진 · 소개 글 · 소식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X14','soc',3,'u1',ARRAY['SO3-1-u1-C5']::text[],'공유 앱에 올리는 방법(사진으로 찍기)이나 좋은 점(더 많은 친구와 나눔)을 잘못 안다','찍어서 올리면 함께 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X15','soc',3,'u1',ARRAY['SO3-1-u1-C5']::text[],'재미있다며 친구 작품을 흉보는 댓글을 단다','고운 말로 칭찬해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X16','soc',3,'u1',ARRAY['SO3-1-u1-C5']::text[],'다른 사람의 전화번호 · 주소 · 사진을 허락 없이 함부로 올린다','남의 정보는 지켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X17','soc',3,'u1',ARRAY['SO3-1-u1-C7']::text[],'도움을 주는 장소를 나 혼자 쓰는 곳으로 여긴다(내 방 · 우리 집)','여러 사람이 함께 이용해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X18','soc',3,'u1',ARRAY['SO3-1-u1-C7','SO3-1-u1-C8']::text[],'병원 · 소방서 · 우체국 · 경찰서 · 도서관이 주는 도움을 바꾸어 안다','어떤 도움을 주나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X19','soc',3,'u1',ARRAY['SO3-1-u1-C7']::text[],'도움을 주는 장소가 없어도 생활에 불편이 없다고 여긴다','없다면 어떨까요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X20','soc',3,'u1',ARRAY['SO3-1-u1-C8']::text[],'하는 일이 다른 장소를 같은 무리로 묶는다(소방서와 도서관을 안전 무리로)','하는 일이 같나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X21','soc',3,'u1',ARRAY['SO3-1-u1-C8']::text[],'정해 둔 무리에 딱 맞지 않는 장소는 묶을 수 없다고 여겨 새 기준을 떠올리지 못한다','새 기준을 만들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X22','soc',3,'u1',ARRAY['SO3-1-u1-C9']::text[],'디지털 영상 지도를 손으로 상상해 그린 그림으로 여긴다','위성 · 항공 사진') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X23','soc',3,'u1',ARRAY['SO3-1-u1-C9']::text[],'디지털 영상 지도로 맛 · 냄새 · 사람의 마음처럼 알 수 없는 것까지 안다고 여긴다','위치 · 가는 길 · 주변 장소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X24','soc',3,'u1',ARRAY['SO3-1-u1-C9','SO3-1-u1-C10']::text[],'장소를 찾을 때 검색하지 않고 화면을 끌기만 하거나 이름과 기호를 보지 않는다','검색하고 이름과 기호를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X25','soc',3,'u1',ARRAY['SO3-1-u1-C10']::text[],'확대(＋)와 축소(－)를 바꾸어 쓴다','＋는 크게 · －는 넓게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X26','soc',3,'u1',ARRAY['SO3-1-u1-C10']::text[],'길찾기에 출발과 도착을 바꾸어 넣거나 길을 알고 싶을 때 다른 기능을 쓴다','출발 → 도착') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X27','soc',3,'u1',ARRAY['SO3-1-u1-C11']::text[],'쓰레기가 많고 시끄럽고 어두운 곳을 살기 좋은 곳의 조건으로 고른다','안전 · 환경 · 편리 · 어울림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X28','soc',3,'u1',ARRAY['SO3-1-u1-C11']::text[],'살기 좋은 곳은 조건 하나(가게가 많음)만 갖추면 된다고 여긴다','여러 조건을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X29','soc',3,'u1',ARRAY['SO3-1-u1-C11']::text[],'조건과 그 예를 바꾸어 짝짓는다(가로등을 어울림으로)','어떤 조건일까요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X30','soc',3,'u1',ARRAY['SO3-1-u1-C12']::text[],'고칠 점을 찾지 않고 방안부터 정하거나 문제와 맞지 않는 방안을 고른다','문제에 맞는 방안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X31','soc',3,'u1',ARRAY['SO3-1-u1-C12']::text[],'동네를 바꾸는 일은 어른만 할 수 있어 나는 할 일이 없다고 여긴다','나도 할 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u1-X32','soc',3,'u1',ARRAY['SO3-1-u1-C12']::text[],'어린이 보호구역의 뜻과 지킬 일을 모른다(차가 빨리 달려도 됨)','어린이를 지키는 구역') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
