INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_basic#8','soc',3,1,'u1','L01','g3_1_soc_u1_L01_basic','lesson_basic','SO3-1-u1-C1',2,'mc','auto','장소와 그곳에서의 경험이 가장 잘 어울리는 것은 무엇일까요?',ARRAY['SO3-1-u1-X04']::text[],false,'{"seq":8,"concept":"SO3-1-u1-C1","difficulty":2,"kind":"mc","stem":"장소와 그곳에서의 경험이 가장 잘 어울리는 것은 무엇일까요?","options":[{"t":"시장 — 할머니와 과일을 샀다","correct":true},{"t":"병원 — 친구와 축구를 했다","mis":"SO3-1-u1-X04"},{"t":"도서관 — 큰 소리로 노래를 불렀다","mis":"SO3-1-u1-X04"},{"t":"강 — 책을 빌렸다","mis":"SO3-1-u1-X04"}],"explanation":["그곳에서 보통 하는 일","시장","물건을 사요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_basic#9','soc',3,1,'u1','L01','g3_1_soc_u1_L01_basic','lesson_basic','SO3-1-u1-C1',2,'mc','auto','필요한 일에 따라 알맞은 장소를 찾아간 친구는 누구일까요?',ARRAY['SO3-1-u1-X04']::text[],false,'{"seq":9,"concept":"SO3-1-u1-C1","difficulty":2,"kind":"mc","stem":"필요한 일에 따라 알맞은 장소를 찾아간 친구는 누구일까요?","options":[{"t":"「신발을 사려고 시장에 갔어.」","correct":true},{"t":"「물놀이를 하려고 도서관에 갔어.」","mis":"SO3-1-u1-X04"},{"t":"「책을 빌리려고 놀이터에 갔어.」","mis":"SO3-1-u1-X04"},{"t":"「공부하려고 냇물에 갔어.」","mis":"SO3-1-u1-X04"}],"explanation":["무엇이 필요한가요?","알맞은 곳","시장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_basic#10','soc',3,1,'u1','L01','g3_1_soc_u1_L01_basic','lesson_basic','SO3-1-u1-C1',3,'mc','auto','「햇살마을 둘러보기」를 보고 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u1-X02','SO3-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"「햇살마을 둘러보기」를 보고 바르게 말한 것은 무엇일까요?","options":[{"t":"한 마을 안에 자연이 만든 곳과 사람이 만든 곳이 함께 있어요.","correct":true},{"t":"마을에는 장소가 하나뿐이에요.","mis":"SO3-1-u1-X02"},{"t":"뒷산과 냇물은 장소가 아니에요.","mis":"SO3-1-u1-X03"},{"t":"모든 장소에서 하는 일이 같아요.","mis":"SO3-1-u1-X02"}],"explanation":["뒷산 · 냇물","학교 · 시장","함께 있어요."],"asset":{"type":"passage","lines":["햇살마을에 있는 곳: 뒷산 · 냇물 · 학교 · 시장 · 도서관 · 놀이터 · 꽃집","뒷산 — 나무가 우거져 산책하기 좋다.","냇물 — 맑은 물이 졸졸 흐른다.","시장 — 과일과 채소를 사고판다.","꽃집 — 여러 가지 꽃을 판다."],"title":"햇살마을 둘러보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#1','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',2,'mc','auto','장소만 바르게 모은 것은 무엇일까요?',ARRAY['SO3-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C1","difficulty":2,"kind":"mc","stem":"장소만 바르게 모은 것은 무엇일까요?","options":[{"t":"산 · 시장 · 놀이터","correct":true},{"t":"어제 · 기쁨 · 산","mis":"SO3-1-u1-X01"},{"t":"빠르다 · 시장 · 내일","mis":"SO3-1-u1-X01"},{"t":"웃음 · 놀이터 · 꿈","mis":"SO3-1-u1-X01"}],"explanation":["찾아갈 수 있나요?","하나씩 따져요.","모두 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#2','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',2,'mc','auto','친구들과 미끄럼틀을 타며 뛰어놀 수 있는 장소는 어디일까요?',ARRAY['SO3-1-u1-X04']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C1","difficulty":2,"kind":"mc","stem":"친구들과 미끄럼틀을 타며 뛰어놀 수 있는 장소는 어디일까요?","options":[{"t":"놀이터","correct":true},{"t":"은행","mis":"SO3-1-u1-X04"},{"t":"도서관","mis":"SO3-1-u1-X04"},{"t":"시장","mis":"SO3-1-u1-X04"}],"explanation":["미끄럼틀","뛰어놀아요.","놀이터"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#3','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',3,'mc','auto','하린이는 「장소는 사람이 지은 건물만이야.」라고 했어요. 알맞게 고쳐 준 말은 무엇일까요?',ARRAY['SO3-1-u1-X03','SO3-1-u1-X01','SO3-1-u1-X02']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"하린이는 「장소는 사람이 지은 건물만이야.」라고 했어요. 알맞게 고쳐 준 말은 무엇일까요?","options":[{"t":"「산이나 강처럼 자연이 만든 곳도 우리가 찾아가는 장소야.」","correct":true},{"t":"「맞아. 건물만 장소야.」","mis":"SO3-1-u1-X03"},{"t":"「장소는 눈에 안 보이는 거야.」","mis":"SO3-1-u1-X01"},{"t":"「장소는 사람이 가지 않는 곳만이야.」","mis":"SO3-1-u1-X02"}],"explanation":["산에 갈 수 있나요?","자연이 만든 곳","장소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#4','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',3,'mc','auto','우리가 여러 장소를 찾아가는 까닭으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X02']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"우리가 여러 장소를 찾아가는 까닭으로 알맞은 것은 무엇일까요?","options":[{"t":"장소마다 하는 일이 달라 필요한 일에 맞는 곳을 찾아가기 때문이에요.","correct":true},{"t":"모든 장소에서 같은 일을 하기 때문이에요.","mis":"SO3-1-u1-X02"},{"t":"장소는 아무 데나 가도 똑같기 때문이에요.","mis":"SO3-1-u1-X02"},{"t":"장소는 한 번만 갈 수 있기 때문이에요.","mis":"SO3-1-u1-X02"}],"explanation":["하는 일이 달라요.","필요한 일","알맞은 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#5','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',3,'mc','auto','햇살마을에서 할머니 생신 선물로 꽃을 사려면 어디로 가야 할까요?',ARRAY['SO3-1-u1-X04']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"햇살마을에서 할머니 생신 선물로 꽃을 사려면 어디로 가야 할까요?","options":[{"t":"꽃집","correct":true},{"t":"냇물","mis":"SO3-1-u1-X04"},{"t":"뒷산","mis":"SO3-1-u1-X04"},{"t":"도서관","mis":"SO3-1-u1-X04"}],"explanation":["꽃을 파는 곳","꽃집","사람이 만든 장소"],"asset":{"type":"passage","lines":["햇살마을에 있는 곳: 뒷산 · 냇물 · 학교 · 시장 · 도서관 · 놀이터 · 꽃집","뒷산 — 나무가 우거져 산책하기 좋다.","냇물 — 맑은 물이 졸졸 흐른다.","시장 — 과일과 채소를 사고판다.","꽃집 — 여러 가지 꽃을 판다."],"title":"햇살마을 둘러보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#6','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',3,'mc','auto','같은 놀이터에 대해 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X01']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"같은 놀이터에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"같은 장소라도 사람마다 경험과 느낌이 다를 수 있어요.","correct":true},{"t":"놀이터에서는 모두 똑같은 느낌이 들어야 해요.","mis":"SO3-1-u1-X09"},{"t":"놀이터는 장소가 아니에요.","mis":"SO3-1-u1-X01"},{"t":"다른 느낌을 말한 친구는 잘못 느낀 거예요.","mis":"SO3-1-u1-X09"}],"explanation":["같은 장소","사람마다","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#7','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',3,'mc','auto','우리 마을의 장소를 친구에게 소개하는 말로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X04','SO3-1-u1-X01']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"우리 마을의 장소를 친구에게 소개하는 말로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「시장은 여러 가지 물건을 사고파는 곳이야.」","correct":true},{"t":"「시장은 책을 빌리는 곳이야.」","mis":"SO3-1-u1-X04"},{"t":"「시장은 물이 흐르는 곳이야.」","mis":"SO3-1-u1-X04"},{"t":"「시장은 어제 일이야.」","mis":"SO3-1-u1-X01"}],"explanation":["시장에서는","사고팔아요.","하는 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#8','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',4,'essay','teacher','우리 동네에 있는 장소 세 곳을 쓰고, 각 장소에서 하는 일을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C1","difficulty":4,"kind":"essay","stem":"우리 동네에 있는 장소 세 곳을 쓰고, 각 장소에서 하는 일을 쓰세요.","answer_guide":{"answer":"예: 학교 — 공부하고 친구들과 지낸다. / 시장 — 여러 가지 물건을 사고판다. / 도서관 — 책을 빌리고 조용히 읽는다.","scoring_points":["장소 세 곳을 썼는가","장소마다 하는 일을 알맞게 썼는가","찾아갈 수 있는 곳만 썼는가"]},"explanation":["어디가 있나요?","무엇을 하나요?","세 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#9','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',4,'essay','teacher','산 · 강 같은 장소와 학교 · 시장 같은 장소는 어떤 점이 다른지 쓰고, 둘 다 장소라고 할 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C1","difficulty":4,"kind":"essay","stem":"산 · 강 같은 장소와 학교 · 시장 같은 장소는 어떤 점이 다른지 쓰고, 둘 다 장소라고 할 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 산과 강은 자연이 만든 곳이고, 학교와 시장은 사람이 만든 곳이다. 하지만 모두 우리가 찾아가서 생활하는 곳이라 장소라고 할 수 있다.","scoring_points":["자연이 만든 곳과 사람이 만든 곳을 바르게 썼는가","찾아갈 수 있는 곳이라는 까닭을 썼는가","예를 바르게 들었는가"]},"explanation":["누가 만들었나요?","찾아갈 수 있나요?","둘 다 장소"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L01_challenge#10','soc',3,1,'u1','L01','g3_1_soc_u1_L01_challenge','lesson_challenge','SO3-1-u1-C1',4,'essay','teacher','내가 자주 가는 장소 한 곳을 골라, 그곳에서 하는 일과 그곳이 우리 생활에 왜 필요한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C1","difficulty":4,"kind":"essay","stem":"내가 자주 가는 장소 한 곳을 골라, 그곳에서 하는 일과 그곳이 우리 생활에 왜 필요한지 쓰세요.","answer_guide":{"answer":"예: 나는 도서관에 자주 간다. 도서관에서는 책을 빌리고 조용히 읽을 수 있다. 책을 사지 않아도 여러 책을 읽을 수 있어서 우리 생활에 꼭 필요하다.","scoring_points":["장소를 골랐는가","하는 일을 썼는가","필요한 까닭을 썼는가"]},"explanation":["어디?","무엇을?","왜 필요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
