INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_basic#8','soc',3,1,'u1','L02','g3_1_soc_u1_L02_basic','lesson_basic','SO3-1-u1-C2',2,'ox','auto','같은 장소들이라도 기준을 바꾸면 다른 무리로 나뉠 수 있어요.',ARRAY['SO3-1-u1-X06']::text[],false,'{"seq":8,"concept":"SO3-1-u1-C2","difficulty":2,"kind":"ox","stem":"같은 장소들이라도 기준을 바꾸면 다른 무리로 나뉠 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 보고 나누느냐에 따라 묶이는 장소가 달라지기 때문에","correct":true},{"t":"한번 나눈 무리는 기준이 바뀌어도 그대로이기 때문에","mis":"SO3-1-u1-X06"}],"mis":"SO3-1-u1-X06","explanation":["기준 ①","기준 ②","무리가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
