INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#3','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',3,'mc','auto','「학교 · 도서관 / 시장 / 놀이터」로 나눈 기준은 무엇일까요?',ARRAY['SO3-1-u1-X06','SO3-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"「학교 · 도서관 / 시장 / 놀이터」로 나눈 기준은 무엇일까요?","options":[{"t":"그곳에서 하는 일","correct":true},{"t":"누가 만들었나","mis":"SO3-1-u1-X06"},{"t":"장소의 색깔","mis":"SO3-1-u1-X05"},{"t":"장소 이름의 길이","mis":"SO3-1-u1-X05"}],"explanation":["배우는 곳","사고파는 곳","노는 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#4','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',3,'mc','auto','분류에 대해 바르게 말한 친구는 누구일까요?',ARRAY['SO3-1-u1-X06','SO3-1-u1-X05','SO3-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"분류에 대해 바르게 말한 친구는 누구일까요?","options":[{"t":"「기준이 달라지면 같은 장소도 다른 무리에 들어갈 수 있어.」","correct":true},{"t":"「시장은 언제나 사고파는 곳 무리에만 들어가.」","mis":"SO3-1-u1-X06"},{"t":"「기준 없이도 잘 나눌 수 있어.」","mis":"SO3-1-u1-X05"},{"t":"「내 기준과 다른 친구는 잘못한 거야.」","mis":"SO3-1-u1-X07"}],"explanation":["기준이 바뀌면","무리도","달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#5','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',3,'mc','auto','하린이가 장소를 「물이 있는 곳 / 물이 없는 곳」으로 나누었어요. 냇물과 같은 무리에 들어갈 곳은 어디일까요?',ARRAY['SO3-1-u1-X05']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"하린이가 장소를 「물이 있는 곳 / 물이 없는 곳」으로 나누었어요. 냇물과 같은 무리에 들어갈 곳은 어디일까요?","options":[{"t":"수영장","correct":true},{"t":"시장","mis":"SO3-1-u1-X05"},{"t":"도서관","mis":"SO3-1-u1-X05"},{"t":"뒷산","mis":"SO3-1-u1-X05"}],"explanation":["기준은 물","냇물","수영장도 물이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#6','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',3,'mc','auto','「사람이 만든 곳: 학교 · 시장 · 강 · 놀이터」에서 잘못 들어간 장소는 무엇일까요?',ARRAY['SO3-1-u1-X03']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"「사람이 만든 곳: 학교 · 시장 · 강 · 놀이터」에서 잘못 들어간 장소는 무엇일까요?","options":[{"t":"강","correct":true},{"t":"학교","mis":"SO3-1-u1-X03"},{"t":"시장","mis":"SO3-1-u1-X03"},{"t":"놀이터","mis":"SO3-1-u1-X03"}],"explanation":["하나씩 따져요.","강은 누가?","자연"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#7','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',3,'mc','auto','친구와 내가 같은 장소들을 서로 다르게 나누었어요. 알맞은 태도는 무엇일까요?',ARRAY['SO3-1-u1-X07','SO3-1-u1-X05']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"친구와 내가 같은 장소들을 서로 다르게 나누었어요. 알맞은 태도는 무엇일까요?","options":[{"t":"서로 어떤 기준으로 나누었는지 묻고 다른 기준도 존중한다","correct":true},{"t":"내 무리가 맞다고 우긴다","mis":"SO3-1-u1-X07"},{"t":"친구 무리를 지운다","mis":"SO3-1-u1-X07"},{"t":"기준은 말하지 않고 무리만 비교한다","mis":"SO3-1-u1-X05"}],"explanation":["기준을 물어요.","다를 수 있어요.","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#8','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',4,'essay','teacher','산 · 강 · 시장 · 학교 · 도서관 · 놀이터를 내가 정한 기준으로 두 무리로 나누고, 그 기준을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C2","difficulty":4,"kind":"essay","stem":"산 · 강 · 시장 · 학교 · 도서관 · 놀이터를 내가 정한 기준으로 두 무리로 나누고, 그 기준을 쓰세요.","answer_guide":{"answer":"예: 기준 — 밖에서 노는 곳인가 / 밖에서 노는 곳: 산 · 강 · 놀이터 / 아닌 곳: 시장 · 학교 · 도서관","scoring_points":["기준을 분명하게 썼는가","두 무리로 빠짐없이 나누었는가","기준에 맞게 나누었는가"]},"explanation":["기준 먼저","두 무리","빠짐없이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#9','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',4,'essay','teacher','같은 장소들을 두 가지 다른 기준으로 나누어 보고, 기준에 따라 무리가 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C2","difficulty":4,"kind":"essay","stem":"같은 장소들을 두 가지 다른 기준으로 나누어 보고, 기준에 따라 무리가 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 「누가 만들었나」로 나누면 산 · 강 / 학교 · 도서관 · 시장이 된다. 「하는 일」로 나누면 학교 · 도서관 / 시장 / 산 · 강(쉬는 곳)이 된다. 기준이 바뀌니 무리도 달라졌다.","scoring_points":["기준 두 가지를 썼는가","기준마다 무리를 나누었는가","무리가 달라진 점을 썼는가"]},"explanation":["기준 ①","기준 ②","달라진 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L02_challenge#10','soc',3,1,'u1','L02','g3_1_soc_u1_L02_challenge','lesson_challenge','SO3-1-u1-C2',4,'essay','teacher','「내가 자주 가는 곳」 기준으로 장소를 나누면 왜 친구와 무리가 다를 수 있는지 쓰고, 그럴 때의 바른 태도를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C2","difficulty":4,"kind":"essay","stem":"「내가 자주 가는 곳」 기준으로 장소를 나누면 왜 친구와 무리가 다를 수 있는지 쓰고, 그럴 때의 바른 태도를 쓰세요.","answer_guide":{"answer":"예: 사람마다 사는 곳과 하는 일이 달라 자주 가는 곳도 다르기 때문이다. 친구의 무리가 나와 달라도 까닭을 묻고 존중한다.","scoring_points":["사람마다 생활이 달라서라고 썼는가","무리가 다를 수 있다고 썼는가","존중하는 태도를 썼는가"]},"explanation":["사람마다","생활이 달라요.","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
