INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_basic#3','soc',3,1,'u1','L03','g3_1_soc_u1_L03_basic','lesson_basic','SO3-1-u1-C3',1,'mc','auto','장소 카드에 담는 세 가지는 무엇일까요?',ARRAY['SO3-1-u1-X10']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C3","difficulty":1,"kind":"mc","stem":"장소 카드에 담는 세 가지는 무엇일까요?","options":[{"t":"장소 이름 · 경험 · 느낌","correct":true},{"t":"장소 이름 · 친구 키 · 날짜","mis":"SO3-1-u1-X10"},{"t":"경험 · 몸무게 · 전화번호","mis":"SO3-1-u1-X10"},{"t":"느낌 · 신발 크기 · 주소","mis":"SO3-1-u1-X10"}],"explanation":["어디?","무슨 일?","어떤 마음?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_basic#4','soc',3,1,'u1','L03','g3_1_soc_u1_L03_basic','lesson_basic','SO3-1-u1-C3',1,'mc','auto','친구와 놀이터에서 신나게 숨바꼭질을 했어요. 이 경험에 어울리는 느낌은 무엇일까요?',ARRAY['SO3-1-u1-X08']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C3","difficulty":1,"kind":"mc","stem":"친구와 놀이터에서 신나게 숨바꼭질을 했어요. 이 경험에 어울리는 느낌은 무엇일까요?","options":[{"t":"즐거웠어요","correct":true},{"t":"놀이터","mis":"SO3-1-u1-X08"},{"t":"숨바꼭질","mis":"SO3-1-u1-X08"},{"t":"친구","mis":"SO3-1-u1-X08"}],"explanation":["신나게 놀았어요.","그때 마음","즐거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_basic#5','soc',3,1,'u1','L03','g3_1_soc_u1_L03_basic','lesson_basic','SO3-1-u1-C3',2,'mc','auto','「민재의 장소 카드」에서 「느낌」에 해당하는 것은 무엇일까요?',ARRAY['SO3-1-u1-X08','SO3-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"mc","stem":"「민재의 장소 카드」에서 「느낌」에 해당하는 것은 무엇일까요?","options":[{"t":"고소하고 즐거웠다","correct":true},{"t":"할머니와 떡을 사 먹었다","mis":"SO3-1-u1-X08"},{"t":"시장","mis":"SO3-1-u1-X08"},{"t":"토요일","mis":"SO3-1-u1-X10"}],"explanation":["그때 마음","고소 · 즐거움","느낌"],"asset":{"type":"passage","lines":["장소 — 시장","경험 — 할머니와 떡을 사 먹었다.","느낌 — 고소하고 즐거웠다."],"title":"민재의 장소 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_basic#6','soc',3,1,'u1','L03','g3_1_soc_u1_L03_basic','lesson_basic','SO3-1-u1-C3',2,'mc','auto','두 친구의 말을 바르게 설명한 것은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X01']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"mc","stem":"두 친구의 말을 바르게 설명한 것은 무엇일까요?","options":[{"t":"같은 장소라도 사람마다 느낌이 다를 수 있어요.","correct":true},{"t":"수아가 잘못 느낀 거예요.","mis":"SO3-1-u1-X09"},{"t":"민재가 잘못 느낀 거예요.","mis":"SO3-1-u1-X09"},{"t":"수영장은 장소가 아니에요.","mis":"SO3-1-u1-X01"}],"explanation":["같은 수영장","다른 느낌","모두 소중해요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"수영장은 시원해서 정말 신나."},{"who":"수아","text":"나는 물이 무서워서 수영장이 조금 겁나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_basic#7','soc',3,1,'u1','L03','g3_1_soc_u1_L03_basic','lesson_basic','SO3-1-u1-C3',2,'ox','auto','같은 도서관에서 한 친구는 편안하고 다른 친구는 답답했다면, 둘 가운데 한 명은 잘못 느낀 거예요.',ARRAY['SO3-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"ox","stem":"같은 도서관에서 한 친구는 편안하고 다른 친구는 답답했다면, 둘 가운데 한 명은 잘못 느낀 거예요.","answer":"X","reason_options":[{"t":"겪은 일과 마음은 사람마다 달라 맞고 그른 것이 아니기 때문에","correct":true},{"t":"같은 장소에서는 모두 같은 느낌이 들어야 하기 때문에","mis":"SO3-1-u1-X09"}],"mis":"SO3-1-u1-X09","explanation":["느낌에","정답이","없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
