INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#2','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',2,'mc','auto','같은 장소에서 느낌이 달라지는 까닭은 무엇일까요?',ARRAY['SO3-1-u1-X02','SO3-1-u1-X09']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"mc","stem":"같은 장소에서 느낌이 달라지는 까닭은 무엇일까요?","options":[{"t":"사람마다, 때마다 겪은 일이 다르기 때문이에요.","correct":true},{"t":"장소가 날마다 바뀌기 때문이에요.","mis":"SO3-1-u1-X02"},{"t":"느낌에 정답이 있기 때문이에요.","mis":"SO3-1-u1-X09"},{"t":"누군가 잘못 느꼈기 때문이에요.","mis":"SO3-1-u1-X09"}],"explanation":["겪은 일이","달라서","느낌도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
