INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#5','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',3,'mc','auto','같은 시장을 두고 「시끄러워요」와 「활기차요」라고 한 두 친구에게 해 줄 말은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X11']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C3","difficulty":3,"kind":"mc","stem":"같은 시장을 두고 「시끄러워요」와 「활기차요」라고 한 두 친구에게 해 줄 말은 무엇일까요?","options":[{"t":"「둘 다 겪은 대로 느낀 거라 모두 소중해.」","correct":true},{"t":"「시끄럽다는 느낌은 잘못이야.」","mis":"SO3-1-u1-X09"},{"t":"「한 가지로 정해야 해.」","mis":"SO3-1-u1-X09"},{"t":"「느낌은 말하면 안 돼.」","mis":"SO3-1-u1-X11"}],"explanation":["같은 시장","다른 느낌","모두 소중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#6','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',3,'mc','auto','느낌을 말할 때 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X08']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C3","difficulty":3,"kind":"mc","stem":"느낌을 말할 때 알맞은 것은 무엇일까요?","options":[{"t":"그 장소에서 겪은 일과 함께 내 마음을 솔직하게 말한다","correct":true},{"t":"남이 좋아할 느낌만 말한다","mis":"SO3-1-u1-X09"},{"t":"겪은 일만 말하고 마음은 뺀다","mis":"SO3-1-u1-X08"},{"t":"친구 느낌을 그대로 따라 한다","mis":"SO3-1-u1-X09"}],"explanation":["겪은 일","내 마음","솔직하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#7','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',3,'mc','auto','친구가 「나는 도서관이 답답해.」라고 했어요. 존중하는 대답은 무엇일까요?',ARRAY['SO3-1-u1-X11','SO3-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C3","difficulty":3,"kind":"mc","stem":"친구가 「나는 도서관이 답답해.」라고 했어요. 존중하는 대답은 무엇일까요?","options":[{"t":"「그렇구나. 왜 그렇게 느꼈는지 궁금해.」","correct":true},{"t":"「도서관이 답답하다니 이상해.」","mis":"SO3-1-u1-X11"},{"t":"「그건 잘못 느낀 거야.」","mis":"SO3-1-u1-X09"},{"t":"「대답하기 싫어.」","mis":"SO3-1-u1-X11"}],"explanation":["다른 느낌","궁금해하기","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#8','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',4,'essay','teacher','내가 가 본 장소 한 곳을 골라 장소 카드를 만들어 쓰세요(장소 이름 · 경험 · 느낌).','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C3","difficulty":4,"kind":"essay","stem":"내가 가 본 장소 한 곳을 골라 장소 카드를 만들어 쓰세요(장소 이름 · 경험 · 느낌).","answer_guide":{"answer":"예: 장소 — 동네 수영장 / 경험 — 형과 물속에서 숨 오래 참기를 했다 / 느낌 — 물속이 조용해서 신기하고 재미있었다.","scoring_points":["장소 이름을 썼는가","경험을 썼는가","그때의 느낌을 썼는가"]},"explanation":["장소","경험","느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#9','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',4,'essay','teacher','두 친구의 느낌이 다른 까닭을 쓰고, 나와 다른 느낌을 들었을 때 어떤 태도를 가져야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C3","difficulty":4,"kind":"essay","stem":"두 친구의 느낌이 다른 까닭을 쓰고, 나와 다른 느낌을 들었을 때 어떤 태도를 가져야 하는지 쓰세요.","answer_guide":{"answer":"예: 민재는 물놀이를 좋아하고 수아는 물이 무서워서 같은 수영장이라도 느낌이 다르다. 나와 다른 느낌을 들으면 놀리지 않고 까닭을 물으며 존중한다.","scoring_points":["겪은 일이나 생각이 달라서라고 썼는가","느낌에 정답이 없다는 점이 드러나는가","존중하는 태도를 썼는가"]},"explanation":["왜 다를까요?","정답 없음","존중"],"asset":{"type":"speech","turns":[{"who":"민재","text":"수영장은 시원해서 정말 신나."},{"who":"수아","text":"나는 물이 무서워서 수영장이 조금 겁나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L03_challenge#10','soc',3,1,'u1','L03','g3_1_soc_u1_L03_challenge','lesson_challenge','SO3-1-u1-C3',4,'essay','teacher','같은 장소에서 때에 따라 느낌이 달랐던 내 경험을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C3","difficulty":4,"kind":"essay","stem":"같은 장소에서 때에 따라 느낌이 달랐던 내 경험을 쓰세요.","answer_guide":{"answer":"예: 운동장에서 운동회 날에는 응원 소리가 커서 신났지만, 방학 때 혼자 갔을 때는 조용해서 조금 쓸쓸했다.","scoring_points":["같은 장소를 골랐는가","두 번의 경험을 썼는가","느낌이 어떻게 달랐는지 썼는가"]},"explanation":["같은 장소","다른 때","다른 느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
