INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#2','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',2,'mc','auto','서로 다른 장소를 좋아하는 친구들이 모였어요. 알맞은 태도는 무엇일까요?',ARRAY['SO3-1-u1-X11']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C4","difficulty":2,"kind":"mc","stem":"서로 다른 장소를 좋아하는 친구들이 모였어요. 알맞은 태도는 무엇일까요?","options":[{"t":"서로 좋아하는 장소와 까닭을 듣고 존중한다","correct":true},{"t":"내가 좋아하는 장소만 좋은 곳이라고 한다","mis":"SO3-1-u1-X11"},{"t":"다른 장소를 좋아하는 친구를 놀린다","mis":"SO3-1-u1-X11"},{"t":"아무 말도 듣지 않는다","mis":"SO3-1-u1-X11"}],"explanation":["저마다","좋아하는 곳","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#3','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',3,'mc','auto','하린이는 냇가에서 물수제비를 뜬 신나는 경험을 친구들이 눈으로 보는 것처럼 느끼게 하고 싶어요. 가장 알맞은 방법은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X13']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C4","difficulty":3,"kind":"mc","stem":"하린이는 냇가에서 물수제비를 뜬 신나는 경험을 친구들이 눈으로 보는 것처럼 느끼게 하고 싶어요. 가장 알맞은 방법은 무엇일까요?","options":[{"t":"냇가의 모습과 물이 튀는 장면을 그림으로 그려 소개한다","correct":true},{"t":"냇가 이름만 적는다","mis":"SO3-1-u1-X12"},{"t":"친구 그림을 베껴 낸다","mis":"SO3-1-u1-X12"},{"t":"신문에 친구 주소를 쓴다","mis":"SO3-1-u1-X13"}],"explanation":["보는 것처럼","모습","그림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#4','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',3,'mc','auto','마을 신문 기사로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X13','SO3-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C4","difficulty":3,"kind":"mc","stem":"마을 신문 기사로 알맞은 것은 무엇일까요?","options":[{"t":"「다음 주부터 도서관이 저녁 일곱 시까지 문을 열어요.」","correct":true},{"t":"「우리 반 민재의 비밀은 …」","mis":"SO3-1-u1-X13"},{"t":"「옆집 전화번호는 …」","mis":"SO3-1-u1-X16"},{"t":"「아무 내용 없음」","mis":"SO3-1-u1-X13"}],"explanation":["마을 사람들에게","알릴 소식","도서관 소식"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
