INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#6','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',3,'mc','auto','같은 시장을 민재는 그림으로, 수아는 노래로 표현했어요. 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X09']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C4","difficulty":3,"kind":"mc","stem":"같은 시장을 민재는 그림으로, 수아는 노래로 표현했어요. 바르게 말한 것은 무엇일까요?","options":[{"t":"같은 장소도 여러 방법으로 표현할 수 있어 둘 다 좋은 표현이에요.","correct":true},{"t":"그림이 아니면 표현이 아니에요.","mis":"SO3-1-u1-X12"},{"t":"둘 중 한 명은 잘못한 거예요.","mis":"SO3-1-u1-X09"},{"t":"노래로는 장소를 나타낼 수 없어요.","mis":"SO3-1-u1-X12"}],"explanation":["같은 시장","다른 방법","모두 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#7','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',3,'mc','auto','모형으로 장소를 표현하면 좋은 점은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C4","difficulty":3,"kind":"mc","stem":"모형으로 장소를 표현하면 좋은 점은 무엇일까요?","options":[{"t":"장소를 입체로 직접 보여 줄 수 있어요.","correct":true},{"t":"장소의 소리를 들려줄 수 있어요.","mis":"SO3-1-u1-X12"},{"t":"글을 많이 쓸 수 있어요.","mis":"SO3-1-u1-X12"},{"t":"사진을 찍지 않아도 공유 앱에 저절로 올라가요.","mis":"SO3-1-u1-X14"}],"explanation":["작게 만들어","입체로","보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#8','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',4,'essay','teacher','내가 좋아하는 장소 한 곳을 골라, 그림 · 신문 · 노래 · 모형 가운데 어떤 방법으로 표현하고 싶은지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C4","difficulty":4,"kind":"essay","stem":"내가 좋아하는 장소 한 곳을 골라, 그림 · 신문 · 노래 · 모형 가운데 어떤 방법으로 표현하고 싶은지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 뒷산을 모형으로 표현하고 싶다. 산의 높낮이와 오솔길을 입체로 만들어 보여 주면 친구들이 산의 모습을 잘 알 수 있기 때문이다.","scoring_points":["장소를 골랐는가","표현 방법을 골랐는가","그 방법을 고른 까닭을 썼는가"]},"explanation":["어디?","어떤 방법?","왜?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#9','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',4,'essay','teacher','우리 마을 신문에 실을 기사 하나를 「사진 · 소개 글 · 소식」으로 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C4","difficulty":4,"kind":"essay","stem":"우리 마을 신문에 실을 기사 하나를 「사진 · 소개 글 · 소식」으로 나누어 쓰세요.","answer_guide":{"answer":"예: 사진 — 새로 생긴 도서관 놀이방 / 소개 글 — 도서관에 그림책을 읽으며 쉴 수 있는 놀이방이 생겼어요. / 소식 — 이번 주 토요일에 그림책 읽어 주기 모임이 열려요.","scoring_points":["사진에 담을 것을 썼는가","소개 글을 썼는가","소식을 썼는가"]},"explanation":["사진","소개 글","소식"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L04_challenge#10','soc',3,1,'u1','L04','g3_1_soc_u1_L04_challenge','lesson_challenge','SO3-1-u1-C4',4,'essay','teacher','친구가 공원을 그린 그림을 소개했어요. 친구 작품의 좋은 점을 찾아 칭찬하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C4","difficulty":4,"kind":"essay","stem":"친구가 공원을 그린 그림을 소개했어요. 친구 작품의 좋은 점을 찾아 칭찬하는 말을 쓰세요.","answer_guide":{"answer":"예: 「공원 나무를 진한 초록색으로 칠해서 정말 시원해 보여. 벤치에 앉아 쉬는 모습도 있어서 공원이 편안하게 느껴져.」","scoring_points":["좋은 점을 구체적으로 찾았는가","고운 말로 썼는가","친구의 표현을 존중하는가"]},"explanation":["무엇이 좋은가요?","구체적으로","고운 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#1','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',1,'mc','auto','공유 앱에 작품을 올리면 좋은 점은 무엇일까요?',ARRAY['SO3-1-u1-X14','SO3-1-u1-X15']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C5","difficulty":1,"kind":"mc","stem":"공유 앱에 작품을 올리면 좋은 점은 무엇일까요?","options":[{"t":"교실 밖 여러 친구도 함께 작품을 볼 수 있어요.","correct":true},{"t":"작품이 저절로 잘 그려져요.","mis":"SO3-1-u1-X14"},{"t":"친구 흉을 볼 수 있어요.","mis":"SO3-1-u1-X15"},{"t":"아무도 볼 수 없어요.","mis":"SO3-1-u1-X14"}],"explanation":["올리면","여러 친구","함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#2','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',1,'mc','auto','내 그림을 공유 앱에 올리려면 먼저 무엇을 할까요?',ARRAY['SO3-1-u1-X14','SO3-1-u1-X16']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C5","difficulty":1,"kind":"mc","stem":"내 그림을 공유 앱에 올리려면 먼저 무엇을 할까요?","options":[{"t":"그림을 사진으로 찍는다","correct":true},{"t":"그림을 접어 둔다","mis":"SO3-1-u1-X14"},{"t":"그림을 지운다","mis":"SO3-1-u1-X14"},{"t":"친구 주소를 적는다","mis":"SO3-1-u1-X16"}],"explanation":["종이 그림","사진으로","찍어서 올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#3','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',1,'mc','auto','친구 작품에 다는 댓글로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X15','SO3-1-u1-X16']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C5","difficulty":1,"kind":"mc","stem":"친구 작품에 다는 댓글로 알맞은 것은 무엇일까요?","options":[{"t":"「색이 정말 예뻐! 공원에 가 보고 싶어졌어.」","correct":true},{"t":"「이게 뭐야, 못 그렸네.」","mis":"SO3-1-u1-X15"},{"t":"「별로야.」","mis":"SO3-1-u1-X15"},{"t":"「너희 집 주소 알려 줘.」","mis":"SO3-1-u1-X16"}],"explanation":["고운 말","좋은 점","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#4','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',1,'ox','auto','공유 앱에 친구의 전화번호를 올려도 돼요.',ARRAY['SO3-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C5","difficulty":1,"kind":"ox","stem":"공유 앱에 친구의 전화번호를 올려도 돼요.","answer":"X","reason_options":[{"t":"다른 사람의 정보를 함부로 올리면 그 사람이 위험해질 수 있기 때문에","correct":true},{"t":"친구 사이니까 무엇이든 올려도 되기 때문에","mis":"SO3-1-u1-X16"}],"mis":"SO3-1-u1-X16","explanation":["남의 정보","함부로","올리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
