INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#8','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',2,'mc','auto','공유 앱으로 작품을 나누면 좋은 점으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X14','SO3-1-u1-X15']::text[],false,'{"seq":8,"concept":"SO3-1-u1-C5","difficulty":2,"kind":"mc","stem":"공유 앱으로 작품을 나누면 좋은 점으로 알맞은 것은 무엇일까요?","options":[{"t":"멀리 있는 친구와도 작품과 생각을 나눌 수 있어요.","correct":true},{"t":"같은 반 친구만 볼 수 있어요.","mis":"SO3-1-u1-X14"},{"t":"댓글은 쓸 수 없어요.","mis":"SO3-1-u1-X14"},{"t":"예절을 지키지 않아도 돼요.","mis":"SO3-1-u1-X15"}],"explanation":["멀리 있어도","함께","나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#9','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',2,'mc','auto','공유 앱을 쓸 때 지켜야 할 예절은 무엇일까요?',ARRAY['SO3-1-u1-X15','SO3-1-u1-X16']::text[],false,'{"seq":9,"concept":"SO3-1-u1-C5","difficulty":2,"kind":"mc","stem":"공유 앱을 쓸 때 지켜야 할 예절은 무엇일까요?","options":[{"t":"고운 말로 쓰고 남의 정보를 함부로 올리지 않는다","correct":true},{"t":"재미있으면 흉봐도 된다","mis":"SO3-1-u1-X15"},{"t":"친구 사진을 허락 없이 올린다","mis":"SO3-1-u1-X16"},{"t":"댓글은 아무렇게나 쓴다","mis":"SO3-1-u1-X15"}],"explanation":["고운 말","흉보지 않기","정보 지키기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_basic#10','soc',3,1,'u1','L05','g3_1_soc_u1_L05_basic','lesson_basic','SO3-1-u1-C5',3,'mc','auto','디지털 도구를 바르게 쓴 친구는 누구일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X15','SO3-1-u1-X14']::text[],false,'{"seq":10,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"디지털 도구를 바르게 쓴 친구는 누구일까요?","options":[{"t":"「수아 그림에 좋은 점을 칭찬하는 댓글을 달았어.」","correct":true},{"t":"「민재 주소를 댓글에 적었어.」","mis":"SO3-1-u1-X16"},{"t":"「재미로 친구 그림을 흉봤어.」","mis":"SO3-1-u1-X15"},{"t":"「친구 그림을 내 것처럼 올렸어.」","mis":"SO3-1-u1-X14"}],"explanation":["고운 말","예절","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#1','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',2,'mc','auto','수아가 친구의 집 주소를 공유 앱에 올리려고 해요. 해 줄 알맞은 말은 무엇일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X15']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C5","difficulty":2,"kind":"mc","stem":"수아가 친구의 집 주소를 공유 앱에 올리려고 해요. 해 줄 알맞은 말은 무엇일까요?","options":[{"t":"「다른 사람의 정보는 함부로 올리면 안 돼.」","correct":true},{"t":"「좋은 생각이야, 올려.」","mis":"SO3-1-u1-X16"},{"t":"「주소에 사진도 같이 올려.」","mis":"SO3-1-u1-X16"},{"t":"「흉보는 말도 같이 써.」","mis":"SO3-1-u1-X15"}],"explanation":["집 주소","남의 정보","지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#2','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',2,'mc','auto','「좋아요」만 누르는 것보다 더 좋은 나눔은 무엇일까요?',ARRAY['SO3-1-u1-X15','SO3-1-u1-X16','SO3-1-u1-X14']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C5","difficulty":2,"kind":"mc","stem":"「좋아요」만 누르는 것보다 더 좋은 나눔은 무엇일까요?","options":[{"t":"좋은 점을 고운 말로 구체적으로 적어 준다","correct":true},{"t":"흉을 본다","mis":"SO3-1-u1-X15"},{"t":"친구 정보를 묻는다","mis":"SO3-1-u1-X16"},{"t":"아무것도 하지 않는다","mis":"SO3-1-u1-X14"}],"explanation":["좋은 점","구체적으로","고운 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#3','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',3,'mc','auto','「이게 뭐야, 진짜 이상해.」라는 댓글을 고운 말로 바꾼 것은 무엇일까요?',ARRAY['SO3-1-u1-X15','SO3-1-u1-X16']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"「이게 뭐야, 진짜 이상해.」라는 댓글을 고운 말로 바꾼 것은 무엇일까요?","options":[{"t":"「어떤 장소를 그린 건지 궁금해. 더 알려 줄래?」","correct":true},{"t":"「이게 뭐야, 진짜 이상해!!」","mis":"SO3-1-u1-X15"},{"t":"「이상하니까 지워.」","mis":"SO3-1-u1-X15"},{"t":"「너희 집 어디야?」","mis":"SO3-1-u1-X16"}],"explanation":["흉보는 말 대신","궁금한 점을","예의 바르게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#4','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',3,'mc','auto','공유 앱에 작품을 올릴 때 함께 쓰면 좋은 설명은 무엇일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X15','SO3-1-u1-X14']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"공유 앱에 작품을 올릴 때 함께 쓰면 좋은 설명은 무엇일까요?","options":[{"t":"그 장소에서의 경험과 느낌을 짧게 쓴다","correct":true},{"t":"내 전화번호를 쓴다","mis":"SO3-1-u1-X16"},{"t":"친구를 흉보는 말을 쓴다","mis":"SO3-1-u1-X15"},{"t":"아무 설명 없이 아무 사진이나 올린다","mis":"SO3-1-u1-X14"}],"explanation":["어떤 장소?","경험 · 느낌","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#5','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',3,'mc','auto','공유 앱에 친구의 얼굴이 나온 사진을 올리고 싶을 때 먼저 할 일은 무엇일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X15']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"공유 앱에 친구의 얼굴이 나온 사진을 올리고 싶을 때 먼저 할 일은 무엇일까요?","options":[{"t":"친구에게 올려도 되는지 먼저 물어본다","correct":true},{"t":"몰래 올린다","mis":"SO3-1-u1-X16"},{"t":"얼굴에 낙서해서 올린다","mis":"SO3-1-u1-X15"},{"t":"친구 이름과 주소도 함께 올린다","mis":"SO3-1-u1-X16"}],"explanation":["친구 얼굴","친구의 정보","허락 먼저"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#6','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',3,'mc','auto','교실에서만 작품을 보여 줄 때와 견주어 공유 앱의 좋은 점은 무엇일까요?',ARRAY['SO3-1-u1-X14','SO3-1-u1-X15']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"교실에서만 작품을 보여 줄 때와 견주어 공유 앱의 좋은 점은 무엇일까요?","options":[{"t":"더 많은 친구가 보고 댓글로 생각을 나눌 수 있다","correct":true},{"t":"작품이 사라진다","mis":"SO3-1-u1-X14"},{"t":"예절을 지키지 않아도 된다","mis":"SO3-1-u1-X15"},{"t":"댓글을 쓸 수 없다","mis":"SO3-1-u1-X14"}],"explanation":["교실","공유 앱","더 많은 친구"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#7','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',3,'mc','auto','좋은 댓글을 모두 고른 것은 무엇일까요?',ARRAY['SO3-1-u1-X15']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"좋은 댓글을 모두 고른 것은 무엇일까요?","options":[{"t":"㉠ · ㉢ · ㉣","correct":true},{"t":"㉠ · ㉡","mis":"SO3-1-u1-X15"},{"t":"㉡ · ㉢","mis":"SO3-1-u1-X15"},{"t":"㉡ 하나","mis":"SO3-1-u1-X15"}],"explanation":["칭찬","물어보기","바람 전하기"],"asset":{"type":"passage","lines":["㉠ 그림 색이 밝아서 보기만 해도 기분이 좋아져!","㉡ 진짜 못 그렸다. 하나도 안 예뻐.","㉢ 어디를 그린 건지 더 알려 줄래? 궁금해!","㉣ 다음엔 시장도 그려 주면 좋겠어."],"title":"공유 앱 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#8','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',4,'essay','teacher','친구가 공유 앱에 올린 「햇살마을 냇가」 그림에 달 고운 댓글을 쓰세요. 좋은 점 하나와 더 궁금한 점 하나를 넣으세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C5","difficulty":4,"kind":"essay","stem":"친구가 공유 앱에 올린 「햇살마을 냇가」 그림에 달 고운 댓글을 쓰세요. 좋은 점 하나와 더 궁금한 점 하나를 넣으세요.","answer_guide":{"answer":"예: 「냇물을 반짝이는 하늘색으로 칠해서 정말 시원해 보여! 냇가에서 무엇을 하며 놀았는지 궁금해.」","scoring_points":["좋은 점을 칭찬했는가","궁금한 점을 예의 바르게 물었는가","고운 말로 썼는가"]},"explanation":["좋은 점","궁금한 점","고운 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#9','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',4,'essay','teacher','공유 앱을 쓸 때 지켜야 할 예절 두 가지를 쓰고, 그 예절을 지켜야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C5","difficulty":4,"kind":"essay","stem":"공유 앱을 쓸 때 지켜야 할 예절 두 가지를 쓰고, 그 예절을 지켜야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 고운 말로 댓글을 쓴다. 다른 사람의 정보를 함부로 올리지 않는다. 흉보는 말은 친구 마음을 다치게 하고, 정보가 퍼지면 그 사람이 위험해질 수 있기 때문이다.","scoring_points":["예절 두 가지를 썼는가","까닭을 썼는가","정보를 지키는 것이 드러나는가"]},"explanation":["고운 말","정보","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L05_challenge#10','soc',3,1,'u1','L05','g3_1_soc_u1_L05_challenge','lesson_challenge','SO3-1-u1-C5',4,'essay','teacher','공유 앱으로 작품을 나누면 좋은 점을 쓰고, 내가 올리고 싶은 작품과 함께 쓸 설명을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C5","difficulty":4,"kind":"essay","stem":"공유 앱으로 작품을 나누면 좋은 점을 쓰고, 내가 올리고 싶은 작품과 함께 쓸 설명을 쓰세요.","answer_guide":{"answer":"예: 교실 밖 친구들도 내 작품을 보고 댓글로 생각을 나눌 수 있다. 「우리 동네 시장 그림이에요. 할머니와 떡을 사 먹어서 즐거웠던 마음을 밝은 색으로 그렸어요.」","scoring_points":["좋은 점을 썼는가","작품 설명에 장소 · 경험 · 느낌을 담았는가","정보를 함부로 넣지 않았는가"]},"explanation":["좋은 점","작품 설명","경험 · 느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#1','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C6',1,'mc','auto','그림일기에 담는 세 가지는 무엇일까요?',ARRAY['SO3-1-u1-X10','SO3-1-u1-X16']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C6","difficulty":1,"kind":"mc","stem":"그림일기에 담는 세 가지는 무엇일까요?","options":[{"t":"장소 · 경험 · 느낌","correct":true},{"t":"장소 · 친구 키 · 몸무게","mis":"SO3-1-u1-X10"},{"t":"경험 · 전화번호 · 주소","mis":"SO3-1-u1-X16"},{"t":"느낌 · 신발 크기 · 날짜만","mis":"SO3-1-u1-X10"}],"explanation":["어디","무슨 일","어떤 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
