INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#3','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C4',1,'mc','auto','경험과 느낌을 다른 사람에게 전하는 방법으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X15']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C4","difficulty":1,"kind":"mc","stem":"경험과 느낌을 다른 사람에게 전하는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"그림이나 신문으로 표현해 소개한다","correct":true},{"t":"혼자만 알고 있는다","mis":"SO3-1-u1-X12"},{"t":"친구 작품을 베낀다","mis":"SO3-1-u1-X12"},{"t":"흉보는 댓글을 단다","mis":"SO3-1-u1-X15"}],"explanation":["표현해서","소개","전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#4','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C5',1,'mc','auto','공유 앱으로 작품을 나눌 때 꼭 지켜야 할 것은 무엇일까요?',ARRAY['SO3-1-u1-X15','SO3-1-u1-X14','SO3-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C5","difficulty":1,"kind":"mc","stem":"공유 앱으로 작품을 나눌 때 꼭 지켜야 할 것은 무엇일까요?","options":[{"t":"고운 말과 예절","correct":true},{"t":"빠르게 쓰기","mis":"SO3-1-u1-X15"},{"t":"많이 올리기","mis":"SO3-1-u1-X14"},{"t":"친구 정보 올리기","mis":"SO3-1-u1-X16"}],"explanation":["고운 말","예절","지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#5','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C6',2,'mc','auto','「하린이의 그림일기」를 완성하려면 무엇을 더 쓰면 좋을까요?',ARRAY['SO3-1-u1-X10','SO3-1-u1-X08']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C6","difficulty":2,"kind":"mc","stem":"「하린이의 그림일기」를 완성하려면 무엇을 더 쓰면 좋을까요?","options":[{"t":"비눗방울이 하늘로 날아가서 신났다","correct":true},{"t":"공원 둘레는 걸어서 10분이다","mis":"SO3-1-u1-X10"},{"t":"동생 신발 크기","mis":"SO3-1-u1-X10"},{"t":"공원의 이름","mis":"SO3-1-u1-X08"}],"explanation":["장소 ○","경험 ○","느낌을 써요."],"asset":{"type":"passage","lines":["장소 — 동네 공원","경험 — 동생과 비눗방울을 불었다.","느낌 — (아직 쓰지 않음)"],"title":"하린이의 그림일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#6','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C3',2,'mc','auto','같은 공원인데 윤서는 「즐거워요」, 도현이는 「더워서 힘들어요」라고 했어요. 바르게 설명한 것은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X01']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"mc","stem":"같은 공원인데 윤서는 「즐거워요」, 도현이는 「더워서 힘들어요」라고 했어요. 바르게 설명한 것은 무엇일까요?","options":[{"t":"같은 장소라도 사람마다 경험과 느낌이 다를 수 있어요.","correct":true},{"t":"도현이가 잘못 느꼈어요.","mis":"SO3-1-u1-X09"},{"t":"윤서가 잘못 느꼈어요.","mis":"SO3-1-u1-X09"},{"t":"공원은 장소가 아니에요.","mis":"SO3-1-u1-X01"}],"explanation":["같은 공원","다른 느낌","모두 소중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#7','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C6',2,'mc','auto','우리 동네를 입체 모형으로 만들 때 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X11','SO3-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C6","difficulty":2,"kind":"mc","stem":"우리 동네를 입체 모형으로 만들 때 알맞은 것은 무엇일까요?","options":[{"t":"동네의 여러 장소를 떠올려 정성껏 만든다","correct":true},{"t":"아무 상자나 쌓아 둔다","mis":"SO3-1-u1-X12"},{"t":"친구 모형을 망가뜨린다","mis":"SO3-1-u1-X11"},{"t":"장소는 하나만 만든다","mis":"SO3-1-u1-X02"}],"explanation":["여러 장소","떠올려","정성껏"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
