INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#9','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C6',2,'ox','auto','그림일기에는 장소 · 경험 · 느낌을 그림과 글로 함께 담아요.',ARRAY['SO3-1-u1-X12']::text[],false,'{"seq":9,"concept":"SO3-1-u1-C6","difficulty":2,"kind":"ox","stem":"그림일기에는 장소 · 경험 · 느낌을 그림과 글로 함께 담아요.","answer":"O","reason_options":[{"t":"셋을 함께 담아야 그날의 일이 생생하게 남기 때문에","correct":true},{"t":"그림만 있으면 글은 없어도 되기 때문에","mis":"SO3-1-u1-X12"}],"mis":"SO3-1-u1-X12","explanation":["그림","글","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_basic#10','soc',3,1,'u1','L06','g3_1_soc_u1_L06_basic','lesson_basic','SO3-1-u1-C6',3,'mc','auto','이 소단원에서 배운 것을 바르게 말한 친구는 누구일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X12','SO3-1-u1-X15']::text[],false,'{"seq":10,"concept":"SO3-1-u1-C6","difficulty":3,"kind":"mc","stem":"이 소단원에서 배운 것을 바르게 말한 친구는 누구일까요?","options":[{"t":"「여러 장소의 경험과 느낌을 표현해 소개하고, 공유 앱으로 예절을 지켜 나눴어.」","correct":true},{"t":"「장소는 모두 같아서 느낌도 같아.」","mis":"SO3-1-u1-X09"},{"t":"「표현은 그림 하나뿐이야.」","mis":"SO3-1-u1-X12"},{"t":"「공유 앱에선 아무 말이나 써도 돼.」","mis":"SO3-1-u1-X15"}],"explanation":["장소 · 느낌","표현 · 소개","공유 · 예절"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#1','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C2',2,'mc','auto','여러 장소를 기준에 따라 비슷한 것끼리 묶는 것을 무엇이라고 했나요?',ARRAY['SO3-1-u1-X05']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C2","difficulty":2,"kind":"mc","stem":"여러 장소를 기준에 따라 비슷한 것끼리 묶는 것을 무엇이라고 했나요?","options":[{"t":"분류","correct":true},{"t":"경험","mis":"SO3-1-u1-X05"},{"t":"표현","mis":"SO3-1-u1-X05"},{"t":"공유","mis":"SO3-1-u1-X05"}],"explanation":["기준","비슷한 것끼리","분류"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#2','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C6',2,'mc','auto','그림일기를 쓰면 좋은 점은 무엇일까요?',ARRAY['SO3-1-u1-X02','SO3-1-u1-X09','SO3-1-u1-X12']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C6","difficulty":2,"kind":"mc","stem":"그림일기를 쓰면 좋은 점은 무엇일까요?","options":[{"t":"그날 그 장소에서의 일과 마음이 생생하게 남아요.","correct":true},{"t":"장소가 저절로 바뀌어요.","mis":"SO3-1-u1-X02"},{"t":"친구 느낌을 따라 쓸 수 있어요.","mis":"SO3-1-u1-X09"},{"t":"아무것도 남지 않아요.","mis":"SO3-1-u1-X12"}],"explanation":["그림과 글","그날의 일","생생하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#3','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C6',3,'mc','auto','그림일기에 「오늘 놀이터에 갔다.」만 쓰여 있어요. 무엇을 더하면 좋을까요?',ARRAY['SO3-1-u1-X10']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C6","difficulty":3,"kind":"mc","stem":"그림일기에 「오늘 놀이터에 갔다.」만 쓰여 있어요. 무엇을 더하면 좋을까요?","options":[{"t":"거기서 겪은 일과 그때의 느낌","correct":true},{"t":"놀이터의 넓이","mis":"SO3-1-u1-X10"},{"t":"친구의 키","mis":"SO3-1-u1-X10"},{"t":"다른 날 날씨","mis":"SO3-1-u1-X10"}],"explanation":["장소 ○","경험?","느낌?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#4','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C3',3,'mc','auto','친구 그림일기에 「나는 바다가 무서웠다.」라고 쓰여 있어요. 알맞은 말은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X11']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C3","difficulty":3,"kind":"mc","stem":"친구 그림일기에 「나는 바다가 무서웠다.」라고 쓰여 있어요. 알맞은 말은 무엇일까요?","options":[{"t":"「그때 무슨 일이 있었는지 궁금해.」","correct":true},{"t":"「바다는 신나는 곳이니 잘못 느낀 거야.」","mis":"SO3-1-u1-X09"},{"t":"「무서운 건 일기에 쓰면 안 돼.」","mis":"SO3-1-u1-X11"},{"t":"「다른 사람 느낌을 따라 써.」","mis":"SO3-1-u1-X09"}],"explanation":["다른 느낌","궁금해하기","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#5','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C4',3,'mc','auto','하린이는 우리 동네 시장을 알리고 싶어요. 마을 신문과 공유 앱을 함께 쓰는 방법으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X14','SO3-1-u1-X12']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C4","difficulty":3,"kind":"mc","stem":"하린이는 우리 동네 시장을 알리고 싶어요. 마을 신문과 공유 앱을 함께 쓰는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"사진 · 소개 글 · 소식을 담아 신문을 만들고, 사진으로 찍어 공유 앱에 올린다","correct":true},{"t":"신문 없이 친구 주소만 올린다","mis":"SO3-1-u1-X16"},{"t":"신문을 만들고 아무에게도 보여 주지 않는다","mis":"SO3-1-u1-X14"},{"t":"친구 신문을 베껴 올린다","mis":"SO3-1-u1-X12"}],"explanation":["신문 만들기","사진 찍기","올리기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#6','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C2',3,'mc','auto','모형에 놓을 장소를 「자연이 만든 곳 / 사람이 만든 곳」으로 바르게 나눈 것은 무엇일까요?',ARRAY['SO3-1-u1-X03']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"모형에 놓을 장소를 「자연이 만든 곳 / 사람이 만든 곳」으로 바르게 나눈 것은 무엇일까요?","options":[{"t":"자연: 뒷산 · 냇물 / 사람: 학교 · 시장","correct":true},{"t":"자연: 학교 · 냇물 / 사람: 뒷산 · 시장","mis":"SO3-1-u1-X03"},{"t":"자연: 시장 · 뒷산 / 사람: 냇물 · 학교","mis":"SO3-1-u1-X03"},{"t":"모두 자연이 만든 곳","mis":"SO3-1-u1-X03"}],"explanation":["뒷산 · 냇물","학교 · 시장","누가 만들었나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#7','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C5',3,'mc','auto','친구가 내 그림일기에 「글씨가 엉망이네.」라는 댓글을 달았어요. 알맞은 대응은 무엇일까요?',ARRAY['SO3-1-u1-X15','SO3-1-u1-X16','SO3-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"친구가 내 그림일기에 「글씨가 엉망이네.」라는 댓글을 달았어요. 알맞은 대응은 무엇일까요?","options":[{"t":"속상한 마음을 고운 말로 전하고 서로 고운 말을 쓰자고 이야기한다","correct":true},{"t":"똑같이 흉보는 댓글을 단다","mis":"SO3-1-u1-X15"},{"t":"친구 정보를 올린다","mis":"SO3-1-u1-X16"},{"t":"작품을 모두 지우고 다시는 안 올린다","mis":"SO3-1-u1-X14"}],"explanation":["속상해요.","고운 말로","이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#8','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C6',4,'essay','teacher','우리 동네에서 있었던 일 하나로 그림일기에 쓸 내용을 장소 · 경험 · 느낌으로 나누어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C6","difficulty":4,"kind":"essay","stem":"우리 동네에서 있었던 일 하나로 그림일기에 쓸 내용을 장소 · 경험 · 느낌으로 나누어 쓰세요.","answer_guide":{"answer":"예: 장소 — 동네 놀이터 / 경험 — 친구와 그네를 높이 타며 누가 더 높이 가나 겨루었다 / 느낌 — 바람이 얼굴에 닿아 시원하고 정말 신났다.","scoring_points":["장소를 썼는가","경험을 썼는가","느낌을 썼는가"]},"explanation":["장소","경험","느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#9','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C6',4,'essay','teacher','이 소단원에서 배운 것 가운데 두 가지를 골라 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C6","difficulty":4,"kind":"essay","stem":"이 소단원에서 배운 것 가운데 두 가지를 골라 정리해 쓰세요.","answer_guide":{"answer":"예: 같은 장소라도 사람마다 경험과 느낌이 달라서 서로 존중해야 한다. 장소의 경험과 느낌을 그림이나 신문으로 표현하고, 공유 앱으로 고운 말을 쓰며 나눌 수 있다.","scoring_points":["배운 것 두 가지를 썼는가","내용이 바른가","자기 말로 정리했는가"]},"explanation":["느낌과 존중","표현과 소개","공유와 예절"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L06_challenge#10','soc',3,1,'u1','L06','g3_1_soc_u1_L06_challenge','lesson_challenge','SO3-1-u1-C6',4,'essay','teacher','친구가 만든 우리 동네 모형을 보고, 좋은 점을 찾아 칭찬하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C6","difficulty":4,"kind":"essay","stem":"친구가 만든 우리 동네 모형을 보고, 좋은 점을 찾아 칭찬하는 말을 쓰세요.","answer_guide":{"answer":"예: 「학교 앞 횡단보도까지 꼼꼼하게 만들어서 우리 동네가 진짜처럼 보여. 시장 지붕 색도 실제와 똑같아서 신기해.」","scoring_points":["좋은 점을 구체적으로 찾았는가","고운 말로 칭찬했는가","작품 내용과 맞는 말인가"]},"explanation":["무엇이 좋은가요?","구체적으로","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
