INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L07_challenge#5','soc',3,1,'u1','L07','g3_1_soc_u1_L07_challenge','lesson_challenge','SO3-1-u1-C7',3,'mc','auto','우리 동네에 병원이 없다면 어떤 점이 불편할까요?',ARRAY['SO3-1-u1-X18','SO3-1-u1-X19','SO3-1-u1-X04']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C7","difficulty":3,"kind":"mc","stem":"우리 동네에 병원이 없다면 어떤 점이 불편할까요?","options":[{"t":"아플 때 가까이에서 치료를 받기 어려워요.","correct":true},{"t":"불이 났을 때 끄기 어려워요.","mis":"SO3-1-u1-X18"},{"t":"아무 불편이 없어요.","mis":"SO3-1-u1-X19"},{"t":"물건을 사기 어려워요.","mis":"SO3-1-u1-X04"}],"explanation":["병원이 없으면","아플 때","불편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L07_challenge#6','soc',3,1,'u1','L07','g3_1_soc_u1_L07_challenge','lesson_challenge','SO3-1-u1-C7',3,'mc','auto','도움을 주는 장소를 이용할 때 바른 태도는 무엇일까요?',ARRAY['SO3-1-u1-X17','SO3-1-u1-X19']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C7","difficulty":3,"kind":"mc","stem":"도움을 주는 장소를 이용할 때 바른 태도는 무엇일까요?","options":[{"t":"여러 사람이 함께 쓰는 곳이니 차례를 지키고 깨끗하게 쓴다","correct":true},{"t":"나만 쓰는 곳이니 마음대로 쓴다","mis":"SO3-1-u1-X17"},{"t":"필요 없을 때 장난 전화를 건다","mis":"SO3-1-u1-X19"},{"t":"물건을 함부로 가져간다","mis":"SO3-1-u1-X17"}],"explanation":["함께 쓰는 곳","차례","깨끗하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L07_challenge#7','soc',3,1,'u1','L07','g3_1_soc_u1_L07_challenge','lesson_challenge','SO3-1-u1-C7',3,'mc','auto','「소방서는 우리 가족만 필요할 때 쓰는 곳이야.」를 바르게 고친 말은 무엇일까요?',ARRAY['SO3-1-u1-X18','SO3-1-u1-X19','SO3-1-u1-X17']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C7","difficulty":3,"kind":"mc","stem":"「소방서는 우리 가족만 필요할 때 쓰는 곳이야.」를 바르게 고친 말은 무엇일까요?","options":[{"t":"「소방서는 여러 사람이 함께 이용하며 우리 모두의 안전을 지켜 주는 곳이야.」","correct":true},{"t":"「소방서는 편지를 보내는 곳이야.」","mis":"SO3-1-u1-X18"},{"t":"「소방서는 없어도 돼.」","mis":"SO3-1-u1-X19"},{"t":"「소방서는 우리 집 안에 있어.」","mis":"SO3-1-u1-X17"}],"explanation":["우리 가족만?","여러 사람","모두의 안전"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L07_challenge#8','soc',3,1,'u1','L07','g3_1_soc_u1_L07_challenge','lesson_challenge','SO3-1-u1-C7',4,'essay','teacher','우리 동네의 도움을 주는 장소 두 곳을 골라, 각 장소가 주는 도움을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C7","difficulty":4,"kind":"essay","stem":"우리 동네의 도움을 주는 장소 두 곳을 골라, 각 장소가 주는 도움을 쓰세요.","answer_guide":{"answer":"예: 병원 — 아픈 사람을 치료해 건강을 돌봐 준다. / 우체국 — 편지와 물건을 멀리까지 보내도록 도와준다.","scoring_points":["장소 두 곳을 썼는가","장소마다 도움을 바르게 썼는가","여러 사람이 함께 이용하는 곳을 골랐는가"]},"explanation":["어디?","어떤 도움?","두 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L07_challenge#9','soc',3,1,'u1','L07','g3_1_soc_u1_L07_challenge','lesson_challenge','SO3-1-u1-C7',4,'essay','teacher','우리 동네에 경찰서가 없다면 어떤 점이 불편할지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C7","difficulty":4,"kind":"essay","stem":"우리 동네에 경찰서가 없다면 어떤 점이 불편할지 쓰세요.","answer_guide":{"answer":"예: 위험한 일이 생겼을 때 빨리 도와줄 사람이 없다. 길을 잃거나 물건을 잃어버렸을 때 도움을 받기 어렵다.","scoring_points":["경찰서가 주는 도움을 떠올렸는가","불편한 점을 썼는가","생활과 이어서 썼는가"]},"explanation":["경찰서는","위험과 질서","없다면?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L07_challenge#10','soc',3,1,'u1','L07','g3_1_soc_u1_L07_challenge','lesson_challenge','SO3-1-u1-C7',4,'essay','teacher','병원 · 소방서 · 우체국의 공통점을 쓰고, 이런 장소를 이용할 때 지킬 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C7","difficulty":4,"kind":"essay","stem":"병원 · 소방서 · 우체국의 공통점을 쓰고, 이런 장소를 이용할 때 지킬 일을 쓰세요.","answer_guide":{"answer":"예: 모두 여러 사람이 함께 이용하며 우리 생활을 편리하고 안전하게 도와준다. 이용할 때는 차례를 지키고 깨끗하게 쓰며 장난 전화를 하지 않는다.","scoring_points":["공통점을 썼는가","지킬 일을 썼는가","여러 사람이 함께 쓴다는 점이 드러나는가"]},"explanation":["공통점","함께 이용","지킬 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
