INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_basic#7','soc',3,1,'u1','L08','g3_1_soc_u1_L08_basic','lesson_basic','SO3-1-u1-C8',2,'mc','auto','도서관에서 하는 일이 아닌 것은 무엇일까요?',ARRAY['SO3-1-u1-X18']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C8","difficulty":2,"kind":"mc","stem":"도서관에서 하는 일이 아닌 것은 무엇일까요?","options":[{"t":"불을 끄는 일","correct":true},{"t":"책을 빌려주는 일","mis":"SO3-1-u1-X18"},{"t":"조용히 책을 읽게 돕는 일","mis":"SO3-1-u1-X18"},{"t":"책 읽기 모임을 여는 일","mis":"SO3-1-u1-X18"}],"explanation":["도서관은","책과 배움","불은 소방서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_basic#8','soc',3,1,'u1','L08','g3_1_soc_u1_L08_basic','lesson_basic','SO3-1-u1-C8',2,'mc','auto','우체국은 안전 · 건강 · 배움 무리에 딱 맞지 않아요. 알맞은 생각은 무엇일까요?',ARRAY['SO3-1-u1-X21','SO3-1-u1-X20','SO3-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO3-1-u1-C8","difficulty":2,"kind":"mc","stem":"우체국은 안전 · 건강 · 배움 무리에 딱 맞지 않아요. 알맞은 생각은 무엇일까요?","options":[{"t":"「생활을 편리하게 돕는 곳」 같은 새 기준을 만들어 묶는다","correct":true},{"t":"어느 무리에도 넣을 수 없으니 빼 버린다","mis":"SO3-1-u1-X21"},{"t":"아무 무리에나 넣는다","mis":"SO3-1-u1-X20"},{"t":"우체국은 도움을 주는 장소가 아니다","mis":"SO3-1-u1-X17"}],"explanation":["딱 맞지 않으면","새 기준","생활을 편리하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_basic#9','soc',3,1,'u1','L08','g3_1_soc_u1_L08_basic','lesson_basic','SO3-1-u1-C8',2,'ox','auto','같은 장소도 기준에 따라 다른 무리에 넣을 수 있어요.',ARRAY['SO3-1-u1-X06']::text[],false,'{"seq":9,"concept":"SO3-1-u1-C8","difficulty":2,"kind":"ox","stem":"같은 장소도 기준에 따라 다른 무리에 넣을 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 보고 나누느냐에 따라 묶이는 무리가 달라지기 때문에","correct":true},{"t":"한 장소는 언제나 한 무리에만 들어가기 때문에","mis":"SO3-1-u1-X06"}],"mis":"SO3-1-u1-X06","explanation":["기준이 바뀌면","무리도","달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_basic#10','soc',3,1,'u1','L08','g3_1_soc_u1_L08_basic','lesson_basic','SO3-1-u1-C8',3,'mc','auto','도움을 주는 장소가 하는 일에 대해 바르게 말한 친구는 누구일까요?',ARRAY['SO3-1-u1-X18','SO3-1-u1-X20','SO3-1-u1-X21']::text[],false,'{"seq":10,"concept":"SO3-1-u1-C8","difficulty":3,"kind":"mc","stem":"도움을 주는 장소가 하는 일에 대해 바르게 말한 친구는 누구일까요?","options":[{"t":"「장소마다 하는 일이 다르고, 비슷한 일을 하는 곳끼리 묶을 수 있어.」","correct":true},{"t":"「모든 장소가 같은 일을 해.」","mis":"SO3-1-u1-X18"},{"t":"「소방서와 도서관은 같은 일을 해.」","mis":"SO3-1-u1-X20"},{"t":"「무리에 안 맞는 장소는 필요 없어.」","mis":"SO3-1-u1-X21"}],"explanation":["하는 일","비슷한 곳끼리","묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
