INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#2','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',2,'mc','auto','「건강을 돌보는 곳」 무리에 넣을 장소는 어디일까요?',ARRAY['SO3-1-u1-X20']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C8","difficulty":2,"kind":"mc","stem":"「건강을 돌보는 곳」 무리에 넣을 장소는 어디일까요?","options":[{"t":"보건소","correct":true},{"t":"경찰서","mis":"SO3-1-u1-X20"},{"t":"우체국","mis":"SO3-1-u1-X20"},{"t":"도서관","mis":"SO3-1-u1-X20"}],"explanation":["건강","예방 주사","보건소"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#3','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',3,'mc','auto','「소방서 · 도서관」을 「안전을 지키는 곳」으로 묶었어요. 무엇을 고치면 좋을까요?',ARRAY['SO3-1-u1-X20','SO3-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C8","difficulty":3,"kind":"mc","stem":"「소방서 · 도서관」을 「안전을 지키는 곳」으로 묶었어요. 무엇을 고치면 좋을까요?","options":[{"t":"도서관은 배움을 돕는 곳이니 다른 무리로 옮긴다","correct":true},{"t":"그대로 둔다","mis":"SO3-1-u1-X20"},{"t":"소방서를 빼고 도서관만 둔다","mis":"SO3-1-u1-X20"},{"t":"무리를 아예 없앤다","mis":"SO3-1-u1-X05"}],"explanation":["도서관이 하는 일","배움","옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#4','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',3,'mc','auto','도움을 주는 장소를 「걸어서 갈 수 있는 곳 / 차를 타고 가는 곳」으로 다시 나누었어요. 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u1-X06','SO3-1-u1-X05']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C8","difficulty":3,"kind":"mc","stem":"도움을 주는 장소를 「걸어서 갈 수 있는 곳 / 차를 타고 가는 곳」으로 다시 나누었어요. 바르게 말한 것은 무엇일까요?","options":[{"t":"기준이 바뀌어 같은 장소도 앞과 다른 무리에 들어갈 수 있어요.","correct":true},{"t":"기준은 하나만 쓸 수 있어요.","mis":"SO3-1-u1-X06"},{"t":"앞의 무리와 반드시 같아야 해요.","mis":"SO3-1-u1-X06"},{"t":"이런 기준으로는 나눌 수 없어요.","mis":"SO3-1-u1-X05"}],"explanation":["새 기준","새 무리","달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
