INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#7','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',3,'mc','auto','보건소에서 하는 일로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X18']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C8","difficulty":3,"kind":"mc","stem":"보건소에서 하는 일로 알맞은 것은 무엇일까요?","options":[{"t":"예방 주사를 놓고 건강을 돌봐요.","correct":true},{"t":"도둑을 잡아요.","mis":"SO3-1-u1-X18"},{"t":"책을 빌려줘요.","mis":"SO3-1-u1-X18"},{"t":"불을 꺼요.","mis":"SO3-1-u1-X18"}],"explanation":["보건소","예방 주사","건강"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#8','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',4,'essay','teacher','병원 · 경찰서 · 도서관 · 소방서를 하는 일에 따라 묶고, 묶은 기준을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C8","difficulty":4,"kind":"essay","stem":"병원 · 경찰서 · 도서관 · 소방서를 하는 일에 따라 묶고, 묶은 기준을 쓰세요.","answer_guide":{"answer":"예: 안전을 지키는 곳 — 경찰서 · 소방서 / 건강을 돌보는 곳 — 병원 / 배움을 돕는 곳 — 도서관. 기준은 그곳에서 하는 일이다.","scoring_points":["기준을 썼는가","하는 일에 맞게 묶었는가","네 장소를 빠짐없이 넣었는가"]},"explanation":["하는 일","묶기","기준"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#9','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',4,'essay','teacher','우체국을 넣을 수 있는 새 무리의 이름을 지어 쓰고, 그 무리에 함께 넣을 수 있는 장소를 하나 더 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C8","difficulty":4,"kind":"essay","stem":"우체국을 넣을 수 있는 새 무리의 이름을 지어 쓰고, 그 무리에 함께 넣을 수 있는 장소를 하나 더 쓰세요.","answer_guide":{"answer":"예: 새 무리 — 생활을 편리하게 돕는 곳. 우체국과 함께 은행도 넣을 수 있다. 둘 다 생활에 필요한 일을 편리하게 도와주기 때문이다.","scoring_points":["새 무리 이름을 지었는가","함께 넣을 장소를 썼는가","까닭이 알맞은가"]},"explanation":["딱 맞지 않으면","새 기준","함께 넣을 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L08_challenge#10','soc',3,1,'u1','L08','g3_1_soc_u1_L08_challenge','lesson_challenge','SO3-1-u1-C8',4,'essay','teacher','같은 장소가 기준에 따라 다른 무리에 들어가는 예를 하나 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C8","difficulty":4,"kind":"essay","stem":"같은 장소가 기준에 따라 다른 무리에 들어가는 예를 하나 들어 쓰세요.","answer_guide":{"answer":"예: 도서관은 「하는 일」로 나누면 배움을 돕는 곳에 들어가고, 「걸어서 갈 수 있는가」로 나누면 우리 집에서 걸어서 갈 수 있는 곳에 들어간다.","scoring_points":["장소를 하나 골랐는가","기준 두 가지를 썼는가","기준마다 들어가는 무리를 썼는가"]},"explanation":["같은 장소","다른 기준","다른 무리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
