INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#1','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',2,'mc','auto','디지털 영상 지도에서 장소를 찾는 차례로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X24']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C9","difficulty":2,"kind":"mc","stem":"디지털 영상 지도에서 장소를 찾는 차례로 알맞은 것은 무엇일까요?","options":[{"t":"이름 검색 → 이름과 기호 확인 → 위치와 가는 길 살피기","correct":true},{"t":"가는 길 → 검색 → 이름 확인","mis":"SO3-1-u1-X24"},{"t":"기호 확인 → 지도 끄기 → 검색","mis":"SO3-1-u1-X24"},{"t":"아무 데나 누르기 → 끝","mis":"SO3-1-u1-X24"}],"explanation":["검색","확인","살피기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#2','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',2,'mc','auto','하늘에서 찍은 사진으로 만든 지도의 좋은 점은 무엇일까요?',ARRAY['SO3-1-u1-X23','SO3-1-u1-X22']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C9","difficulty":2,"kind":"mc","stem":"하늘에서 찍은 사진으로 만든 지도의 좋은 점은 무엇일까요?","options":[{"t":"건물과 길의 실제 모습을 자세히 볼 수 있어요.","correct":true},{"t":"장소의 소리를 들을 수 있어요.","mis":"SO3-1-u1-X23"},{"t":"사람의 마음을 알 수 있어요.","mis":"SO3-1-u1-X23"},{"t":"상상해서 그린 모습을 볼 수 있어요.","mis":"SO3-1-u1-X22"}],"explanation":["사진이라","실제 모습","자세히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#3','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',3,'mc','auto','하린이가 「도서관이 어디 있지?」 하며 지도를 이리저리 끌기만 해요. 알려 줄 말은 무엇일까요?',ARRAY['SO3-1-u1-X24','SO3-1-u1-X22','SO3-1-u1-X23']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"하린이가 「도서관이 어디 있지?」 하며 지도를 이리저리 끌기만 해요. 알려 줄 말은 무엇일까요?","options":[{"t":"「검색창에 도서관을 입력하면 바로 찾을 수 있어.」","correct":true},{"t":"「계속 끌다 보면 나와.」","mis":"SO3-1-u1-X24"},{"t":"「지도로는 찾을 수 없어.」","mis":"SO3-1-u1-X22"},{"t":"「도서관 냄새를 맡아 봐.」","mis":"SO3-1-u1-X23"}],"explanation":["이름을 알면","검색","바로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#4','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',3,'mc','auto','지도에서 병원을 찾은 다음 더 알아볼 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u1-X23']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"지도에서 병원을 찾은 다음 더 알아볼 수 있는 것은 무엇일까요?","options":[{"t":"병원까지 가는 길과 둘레에 있는 다른 장소","correct":true},{"t":"병원 의사 선생님의 이름","mis":"SO3-1-u1-X23"},{"t":"병원 음식의 맛","mis":"SO3-1-u1-X23"},{"t":"병원을 다녀온 사람의 느낌","mis":"SO3-1-u1-X23"}],"explanation":["위치 다음","가는 길","주변 장소"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#5','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',3,'mc','auto','디지털 영상 지도에 대해 바르게 말한 친구는 누구일까요?',ARRAY['SO3-1-u1-X22','SO3-1-u1-X23','SO3-1-u1-X24']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"디지털 영상 지도에 대해 바르게 말한 친구는 누구일까요?","options":[{"t":"「장소 이름을 검색하면 위치를 쉽게 찾을 수 있어.」","correct":true},{"t":"「손으로 그린 그림이라 실제와 달라.」","mis":"SO3-1-u1-X22"},{"t":"「맛집 맛도 알려 줘.」","mis":"SO3-1-u1-X23"},{"t":"「검색은 쓸 수 없어.」","mis":"SO3-1-u1-X24"}],"explanation":["검색","위치","쉽게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#6','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',3,'mc','auto','우리 집 둘레에 어떤 도움 주는 장소가 있는지 알고 싶어요. 알맞은 방법은 무엇일까요?',ARRAY['SO3-1-u1-X24','SO3-1-u1-X22','SO3-1-u1-X16']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"우리 집 둘레에 어떤 도움 주는 장소가 있는지 알고 싶어요. 알맞은 방법은 무엇일까요?","options":[{"t":"지도에서 우리 집을 찾고 둘레에 표시된 이름과 기호를 살펴본다","correct":true},{"t":"지도를 끄고 짐작한다","mis":"SO3-1-u1-X24"},{"t":"우리 집만 크게 그려 본다","mis":"SO3-1-u1-X22"},{"t":"친구 집 주소를 공유 앱에 올린다","mis":"SO3-1-u1-X16"}],"explanation":["우리 집 찾기","둘레","이름과 기호"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#7','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',3,'mc','auto','지도에 표시된 「병 · 소 · 도」 같은 글자가 하는 일은 무엇일까요?',ARRAY['SO3-1-u1-X23','SO3-1-u1-X24','SO3-1-u1-X22']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"지도에 표시된 「병 · 소 · 도」 같은 글자가 하는 일은 무엇일까요?","options":[{"t":"어떤 장소인지 알려 주는 이름과 기호예요.","correct":true},{"t":"그 장소의 맛을 알려 줘요.","mis":"SO3-1-u1-X23"},{"t":"아무 뜻 없는 그림이에요.","mis":"SO3-1-u1-X24"},{"t":"사진을 찍은 날짜예요.","mis":"SO3-1-u1-X22"}],"explanation":["병 · 소 · 도","이름과 기호","어떤 장소"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#8','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',4,'essay','teacher','디지털 영상 지도로 할 수 있는 일 두 가지를 쓰고, 할 수 없는 일 한 가지를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C9","difficulty":4,"kind":"essay","stem":"디지털 영상 지도로 할 수 있는 일 두 가지를 쓰고, 할 수 없는 일 한 가지를 쓰세요.","answer_guide":{"answer":"예: 할 수 있는 일 — 장소 이름을 검색해 위치를 찾는다. 두 장소 사이의 가는 길을 찾는다. / 할 수 없는 일 — 그 장소의 냄새를 맡는다.","scoring_points":["할 수 있는 일 두 가지를 썼는가","할 수 없는 일을 썼는가","내용이 바른가"]},"explanation":["검색","가는 길","맛 · 냄새는?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#9','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',4,'essay','teacher','디지털 영상 지도로 우리 동네에서 가장 가까운 병원을 찾는 방법을 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C9","difficulty":4,"kind":"essay","stem":"디지털 영상 지도로 우리 동네에서 가장 가까운 병원을 찾는 방법을 차례대로 쓰세요.","answer_guide":{"answer":"예: 먼저 검색창에 「병원」을 입력한다. 다음으로 지도에 표시된 이름과 기호를 보고 우리 집에서 가장 가까운 병원을 찾는다. 마지막으로 그 병원까지 가는 길을 살펴본다.","scoring_points":["검색을 썼는가","이름과 기호 확인을 썼는가","차례가 알맞은가"]},"explanation":["검색","확인","가는 길"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L09_challenge#10','soc',3,1,'u1','L09','g3_1_soc_u1_L09_challenge','lesson_challenge','SO3-1-u1-C9',4,'essay','teacher','디지털 영상 지도가 종이 지도와 견주어 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C9","difficulty":4,"kind":"essay","stem":"디지털 영상 지도가 종이 지도와 견주어 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 위성 · 항공 사진이라 건물과 길의 실제 모습을 볼 수 있다. 검색하면 장소를 빨리 찾고 크게 확대해 자세히 볼 수 있다.","scoring_points":["좋은 점 두 가지를 썼는가","실제 사진이라는 점을 썼는가","검색이나 확대를 썼는가"]},"explanation":["실제 모습","검색","확대"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
