INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#4','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',3,'mc','auto','디지털 영상 지도를 바르게 쓴 친구는 누구일까요?',ARRAY['SO3-1-u1-X25','SO3-1-u1-X26','SO3-1-u1-X24']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C10","difficulty":3,"kind":"mc","stem":"디지털 영상 지도를 바르게 쓴 친구는 누구일까요?","options":[{"t":"「검색으로 위치를 찾고, 길찾기로 가는 길을 확인했어.」","correct":true},{"t":"「멀리 넓게 보려고 ＋만 계속 눌렀어.」","mis":"SO3-1-u1-X25"},{"t":"「가는 길을 알려고 위성 보기만 눌렀어.」","mis":"SO3-1-u1-X26"},{"t":"「이름을 알면서도 화면을 끌기만 했어.」","mis":"SO3-1-u1-X24"}],"explanation":["검색","길찾기","알맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#5','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',3,'mc','auto','위성 보기를 쓰면 좋을 때는 언제일까요?',ARRAY['SO3-1-u1-X26','SO3-1-u1-X25','SO3-1-u1-X24']::text[],false,'{"seq":5,"concept":"SO3-1-u1-C10","difficulty":3,"kind":"mc","stem":"위성 보기를 쓰면 좋을 때는 언제일까요?","options":[{"t":"실제 건물과 길이 어떻게 생겼는지 사진처럼 보고 싶을 때","correct":true},{"t":"가는 길을 알고 싶을 때","mis":"SO3-1-u1-X26"},{"t":"넓게 보고 싶을 때","mis":"SO3-1-u1-X25"},{"t":"장소 이름으로 찾고 싶을 때","mis":"SO3-1-u1-X24"}],"explanation":["위성","사진","실제 모습"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#6','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',3,'mc','auto','기능과 쓰임이 바르게 짝지어진 것은 무엇일까요?',ARRAY['SO3-1-u1-X25','SO3-1-u1-X26']::text[],false,'{"seq":6,"concept":"SO3-1-u1-C10","difficulty":3,"kind":"mc","stem":"기능과 쓰임이 바르게 짝지어진 것은 무엇일까요?","options":[{"t":"축소 — 더 넓은 곳을 한눈에 봐요","correct":true},{"t":"확대 — 더 넓은 곳을 한눈에 봐요","mis":"SO3-1-u1-X25"},{"t":"위성 보기 — 출발과 도착을 정해요","mis":"SO3-1-u1-X26"},{"t":"길찾기 — 실제 모습을 사진으로 봐요","mis":"SO3-1-u1-X26"}],"explanation":["축소는","넓게","하나씩 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#7','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',3,'mc','auto','처음 가는 수영장까지 걸어서 가려고 해요. 디지털 영상 지도로 할 일을 바르게 고른 것은 무엇일까요?',ARRAY['SO3-1-u1-X25','SO3-1-u1-X26']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C10","difficulty":3,"kind":"mc","stem":"처음 가는 수영장까지 걸어서 가려고 해요. 디지털 영상 지도로 할 일을 바르게 고른 것은 무엇일까요?","options":[{"t":"수영장을 검색하고 길찾기로 우리 집에서 가는 길을 본다","correct":true},{"t":"수영장 사진만 확대해 본다","mis":"SO3-1-u1-X25"},{"t":"지도를 축소만 한다","mis":"SO3-1-u1-X25"},{"t":"위성 보기만 켠다","mis":"SO3-1-u1-X26"}],"explanation":["검색","길찾기","가는 길"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#8','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',4,'essay','teacher','디지털 영상 지도의 기능 가운데 두 가지를 골라, 각각 언제 쓰면 좋은지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C10","difficulty":4,"kind":"essay","stem":"디지털 영상 지도의 기능 가운데 두 가지를 골라, 각각 언제 쓰면 좋은지 쓰세요.","answer_guide":{"answer":"예: 확대 — 병원 건물처럼 한 곳을 크고 자세하게 보고 싶을 때 쓴다. / 길찾기 — 집에서 도서관까지 가는 길을 알고 싶을 때 출발과 도착을 넣어 쓴다.","scoring_points":["기능 두 가지를 골랐는가","쓰임을 바르게 썼는가","상황 예를 들었는가"]},"explanation":["어떤 기능?","언제?","두 가지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#9','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',4,'essay','teacher','디지털 영상 지도로 우리 집에서 도서관까지 가는 길을 찾는 차례를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C10","difficulty":4,"kind":"essay","stem":"디지털 영상 지도로 우리 집에서 도서관까지 가는 길을 찾는 차례를 쓰세요.","answer_guide":{"answer":"예: 검색창에 도서관을 입력해 위치를 찾는다. ＋나 －로 크기를 맞추어 둘레를 살핀다. 길찾기에서 출발은 우리 집, 도착은 도서관으로 넣어 가는 길을 확인한다.","scoring_points":["검색을 먼저 썼는가","길찾기의 출발 · 도착을 바르게 썼는가","차례가 알맞은가"]},"explanation":["검색","크기 맞추기","길찾기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L10_challenge#10','soc',3,1,'u1','L10','g3_1_soc_u1_L10_challenge','lesson_challenge','SO3-1-u1-C10',4,'essay','teacher','＋(확대)와 －(축소)는 어떻게 다른지 쓰고, 각각 어떤 때 누르면 좋은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C10","difficulty":4,"kind":"essay","stem":"＋(확대)와 －(축소)는 어떻게 다른지 쓰고, 각각 어떤 때 누르면 좋은지 쓰세요.","answer_guide":{"answer":"예: ＋는 지도를 크게 해서 좁은 곳을 자세히 보여 주고, －는 지도를 작게 해서 넓은 곳을 한눈에 보여 준다. 건물 모양을 보려면 ＋를, 동네 전체를 보려면 －를 누른다.","scoring_points":["확대와 축소의 차이를 썼는가","각각 쓰는 때를 썼는가","바꾸어 쓰지 않았는가"]},"explanation":["＋","－","언제?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_basic#1','soc',3,1,'u1','L11','g3_1_soc_u1_L11_basic','lesson_basic','SO3-1-u1-C11',1,'mc','auto','살기 좋은 곳의 조건으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X27']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C11","difficulty":1,"kind":"mc","stem":"살기 좋은 곳의 조건으로 알맞은 것은 무엇일까요?","options":[{"t":"밝은 가로등이 있어 밤에도 안심하고 다닐 수 있다","correct":true},{"t":"쓰레기가 많고 시끄럽다","mis":"SO3-1-u1-X27"},{"t":"어둡고 위험한 길이 많다","mis":"SO3-1-u1-X27"},{"t":"이웃끼리 인사도 하지 않는다","mis":"SO3-1-u1-X27"}],"explanation":["안심","밝은 길","안전"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
