INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_challenge#3','soc',3,1,'u1','L11','g3_1_soc_u1_L11_challenge','lesson_challenge','SO3-1-u1-C11',3,'mc','auto','우리 동네를 살펴보니 가로등은 밝고 공원도 깨끗하고 이웃도 인사를 잘하지만, 도서관이 아주 멀어요. 고칠 점과 조건을 바르게 짝지은 것은 무엇일까요?',ARRAY['SO3-1-u1-X29','SO3-1-u1-X28']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C11","difficulty":3,"kind":"mc","stem":"우리 동네를 살펴보니 가로등은 밝고 공원도 깨끗하고 이웃도 인사를 잘하지만, 도서관이 아주 멀어요. 고칠 점과 조건을 바르게 짝지은 것은 무엇일까요?","options":[{"t":"도서관이 멀다 — 편리","correct":true},{"t":"가로등 — 편리","mis":"SO3-1-u1-X29"},{"t":"공원 — 어울림","mis":"SO3-1-u1-X29"},{"t":"고칠 점이 없다","mis":"SO3-1-u1-X28"}],"explanation":["무엇이 아쉬운가요?","도서관이 멀어요.","편리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_challenge#4','soc',3,1,'u1','L11','g3_1_soc_u1_L11_challenge','lesson_challenge','SO3-1-u1-C11',3,'mc','auto','가 마을은 가로등이 밝고 공원이 깨끗하며 병원이 가까워요. 나 마을은 큰 가게는 많지만 길이 어둡고 쓰레기가 쌓여 있어요. 더 살기 좋은 곳은 어디일까요?',ARRAY['SO3-1-u1-X28','SO3-1-u1-X27']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C11","difficulty":3,"kind":"mc","stem":"가 마을은 가로등이 밝고 공원이 깨끗하며 병원이 가까워요. 나 마을은 큰 가게는 많지만 길이 어둡고 쓰레기가 쌓여 있어요. 더 살기 좋은 곳은 어디일까요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"SO3-1-u1-X28"},{"t":"두 마을이 같다","mis":"SO3-1-u1-X28"},{"t":"알 수 없다","mis":"SO3-1-u1-X27"}],"explanation":["조건을 세어요.","가 마을은 여럿","나 마을은 가게만"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
