INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_challenge#7','soc',3,1,'u1','L11','g3_1_soc_u1_L11_challenge','lesson_challenge','SO3-1-u1-C11',3,'mc','auto','살기 좋은 곳을 생각할 때 바른 태도는 무엇일까요?',ARRAY['SO3-1-u1-X28','SO3-1-u1-X27']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C11","difficulty":3,"kind":"mc","stem":"살기 좋은 곳을 생각할 때 바른 태도는 무엇일까요?","options":[{"t":"나뿐 아니라 이웃 모두가 편안하게 지낼 수 있는지 함께 생각한다","correct":true},{"t":"나에게 편하면 다른 사람은 상관없다","mis":"SO3-1-u1-X28"},{"t":"조건 하나만 따진다","mis":"SO3-1-u1-X28"},{"t":"쓰레기가 많아도 괜찮다","mis":"SO3-1-u1-X27"}],"explanation":["나만?","모두","함께 생각"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_challenge#8','soc',3,1,'u1','L11','g3_1_soc_u1_L11_challenge','lesson_challenge','SO3-1-u1-C11',4,'essay','teacher','우리 동네를 살기 좋은 곳의 조건에 비추어 좋은 점 하나와 고칠 점 하나를 쓰고, 각각 어떤 조건과 관련 있는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C11","difficulty":4,"kind":"essay","stem":"우리 동네를 살기 좋은 곳의 조건에 비추어 좋은 점 하나와 고칠 점 하나를 쓰고, 각각 어떤 조건과 관련 있는지 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 집 가까이에 도서관과 병원이 있다(편리). / 고칠 점 — 놀이터 옆 길이 밤에 어둡다(안전).","scoring_points":["좋은 점을 썼는가","고칠 점을 썼는가","조건을 바르게 짝지었는가"]},"explanation":["좋은 점","고칠 점","조건"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_challenge#9','soc',3,1,'u1','L11','g3_1_soc_u1_L11_challenge','lesson_challenge','SO3-1-u1-C11',4,'essay','teacher','내가 살고 싶은 동네의 모습을 살기 좋은 곳의 조건 두 가지를 넣어 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C11","difficulty":4,"kind":"essay","stem":"내가 살고 싶은 동네의 모습을 살기 좋은 곳의 조건 두 가지를 넣어 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 나무가 많은 깨끗한 공원이 있고(환경), 이웃끼리 서로 인사하는(어울림) 동네에서 살고 싶다. 공원에서 맑은 공기를 마시며 쉬고, 이웃과 사이좋게 지내면 마음이 편하기 때문이다.","scoring_points":["조건 두 가지를 넣었는가","조건에 맞는 모습을 썼는가","까닭을 썼는가"]},"explanation":["어떤 동네?","조건","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L11_challenge#10','soc',3,1,'u1','L11','g3_1_soc_u1_L11_challenge','lesson_challenge','SO3-1-u1-C11',4,'essay','teacher','「바람마을 소식」의 문장 ①~④가 각각 살기 좋은 곳의 어떤 조건을 보여 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C11","difficulty":4,"kind":"essay","stem":"「바람마을 소식」의 문장 ①~④가 각각 살기 좋은 곳의 어떤 조건을 보여 주는지 쓰세요.","answer_guide":{"answer":"예: ① 안전 — 가로등이 밝다. ② 환경 — 공원이 깨끗하고 나무가 많다. ③ 편리 — 병원과 도서관이 가깝다. ④ 어울림 — 이웃이 서로 인사한다.","scoring_points":["네 문장의 조건을 모두 썼는가","조건을 바르게 짝지었는가","근거가 드러나는가"]},"explanation":["①","②③","④"],"asset":{"type":"passage","lines":["① 밤에도 골목마다 가로등이 환하다.","② 마을 가운데 공원에 나무가 많고 깨끗하다.","③ 걸어서 가까운 곳에 병원과 도서관이 있다.","④ 이웃들이 아침마다 서로 인사한다."],"title":"바람마을 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_basic#1','soc',3,1,'u1','L12','g3_1_soc_u1_L12_basic','lesson_basic','SO3-1-u1-C12',1,'mc','auto','우리 동네를 더 살기 좋게 만드는 첫걸음은 무엇일까요?',ARRAY['SO3-1-u1-X30','SO3-1-u1-X31']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C12","difficulty":1,"kind":"mc","stem":"우리 동네를 더 살기 좋게 만드는 첫걸음은 무엇일까요?","options":[{"t":"불편한 점이나 고칠 점을 찾는다","correct":true},{"t":"아무 방안이나 먼저 정한다","mis":"SO3-1-u1-X30"},{"t":"다른 동네를 탓한다","mis":"SO3-1-u1-X31"},{"t":"어른들에게만 맡긴다","mis":"SO3-1-u1-X31"}],"explanation":["먼저","고칠 점","찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
