INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_basic#9','soc',3,1,'u1','L12','g3_1_soc_u1_L12_basic','lesson_basic','SO3-1-u1-C12',2,'ox','auto','어린이 보호구역에서는 차가 빨리 달려도 괜찮아요.',ARRAY['SO3-1-u1-X32']::text[],false,'{"seq":9,"concept":"SO3-1-u1-C12","difficulty":2,"kind":"ox","stem":"어린이 보호구역에서는 차가 빨리 달려도 괜찮아요.","answer":"X","reason_options":[{"t":"어린이가 안전하게 다니도록 차가 천천히 다니기로 정한 곳이기 때문에","correct":true},{"t":"학교 앞은 넓은 길이라 빨리 가도 되기 때문에","mis":"SO3-1-u1-X32"}],"mis":"SO3-1-u1-X32","explanation":["어린이 보호구역","천천히","안전"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_basic#10','soc',3,1,'u1','L12','g3_1_soc_u1_L12_basic','lesson_basic','SO3-1-u1-C12',3,'mc','auto','더 살기 좋은 곳을 만드는 순서로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X30','SO3-1-u1-X31']::text[],false,'{"seq":10,"concept":"SO3-1-u1-C12","difficulty":3,"kind":"mc","stem":"더 살기 좋은 곳을 만드는 순서로 알맞은 것은 무엇일까요?","options":[{"t":"고칠 점 찾기 → 알맞은 방안 정하기 → 함께 실천하기","correct":true},{"t":"실천하기 → 고칠 점 찾기 → 끝","mis":"SO3-1-u1-X30"},{"t":"방안 정하기 → 그냥 두기","mis":"SO3-1-u1-X31"},{"t":"고칠 점 찾기 → 불평하기","mis":"SO3-1-u1-X31"}],"explanation":["찾기","정하기","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#1','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',2,'mc','auto','「우리 동네의 고칠 점」 ㉡에 알맞은 방안은 무엇일까요?',ARRAY['SO3-1-u1-X30']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C12","difficulty":2,"kind":"mc","stem":"「우리 동네의 고칠 점」 ㉡에 알맞은 방안은 무엇일까요?","options":[{"t":"정류장 둘레에 쓰레기통을 두고 쓰레기를 되가져가자고 알린다","correct":true},{"t":"가로등을 단다","mis":"SO3-1-u1-X30"},{"t":"공원 의자를 만든다","mis":"SO3-1-u1-X30"},{"t":"차가 천천히 달리게 한다","mis":"SO3-1-u1-X30"}],"explanation":["㉡은","쓰레기","맞는 방안"],"asset":{"type":"passage","lines":["㉠ 놀이터 옆 길이 밤에 어둡다.","㉡ 버스 정류장 둘레에 쓰레기가 쌓여 있다.","㉢ 앉아서 쉴 곳이 없다.","㉣ 학교 앞에서 차가 빨리 달린다."],"title":"우리 동네의 고칠 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#2','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',2,'mc','auto','「우리 동네의 고칠 점」 ㉣과 관련된 방안은 무엇일까요?',ARRAY['SO3-1-u1-X30','SO3-1-u1-X32']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C12","difficulty":2,"kind":"mc","stem":"「우리 동네의 고칠 점」 ㉣과 관련된 방안은 무엇일까요?","options":[{"t":"학교 앞 어린이 보호구역에서 차가 천천히 다니도록 알린다","correct":true},{"t":"쓰레기를 분리배출한다","mis":"SO3-1-u1-X30"},{"t":"공원에 의자를 놓는다","mis":"SO3-1-u1-X30"},{"t":"학교 앞 가로등을 끈다","mis":"SO3-1-u1-X32"}],"explanation":["㉣은","학교 앞 차","어린이 보호구역"],"asset":{"type":"passage","lines":["㉠ 놀이터 옆 길이 밤에 어둡다.","㉡ 버스 정류장 둘레에 쓰레기가 쌓여 있다.","㉢ 앉아서 쉴 곳이 없다.","㉣ 학교 앞에서 차가 빨리 달린다."],"title":"우리 동네의 고칠 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#3','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',3,'mc','auto','「내가 바로 할 일」과 「함께 할 일」을 바르게 나눈 것은 무엇일까요?',ARRAY['SO3-1-u1-X31']::text[],false,'{"seq":3,"concept":"SO3-1-u1-C12","difficulty":3,"kind":"mc","stem":"「내가 바로 할 일」과 「함께 할 일」을 바르게 나눈 것은 무엇일까요?","options":[{"t":"내가 바로: 쓰레기 안 버리기 / 함께: 공원 만들기를 의견 내고 의논하기","correct":true},{"t":"내가 바로: 가로등 세우기 / 함께: 인사하기","mis":"SO3-1-u1-X31"},{"t":"내가 바로: 아무것도 없음 / 함께: 어른에게 맡기기","mis":"SO3-1-u1-X31"},{"t":"내가 바로: 불평하기 / 함께: 남 탓하기","mis":"SO3-1-u1-X31"}],"explanation":["작은 실천","함께하는 제안","둘 다 소중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#4','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',3,'mc','auto','하린이는 「어린이는 동네를 바꿀 수 없어.」라고 했어요. 알맞은 대답은 무엇일까요?',ARRAY['SO3-1-u1-X31']::text[],false,'{"seq":4,"concept":"SO3-1-u1-C12","difficulty":3,"kind":"mc","stem":"하린이는 「어린이는 동네를 바꿀 수 없어.」라고 했어요. 알맞은 대답은 무엇일까요?","options":[{"t":"「작은 실천과 의견 내기로 어린이도 동네를 바꾸는 데 힘을 보탤 수 있어.」","correct":true},{"t":"「맞아, 어른만 할 수 있어.」","mis":"SO3-1-u1-X31"},{"t":"「불편해도 그냥 참아.」","mis":"SO3-1-u1-X31"},{"t":"「다른 동네로 이사 가면 돼.」","mis":"SO3-1-u1-X31"}],"explanation":["어린이도","실천","의견"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
