INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#7','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',3,'mc','auto','어린이 보호구역에서 어린이가 지킬 일은 무엇일까요?',ARRAY['SO3-1-u1-X32']::text[],false,'{"seq":7,"concept":"SO3-1-u1-C12","difficulty":3,"kind":"mc","stem":"어린이 보호구역에서 어린이가 지킬 일은 무엇일까요?","options":[{"t":"횡단보도로 건너고 좌우를 살핀다","correct":true},{"t":"차가 천천히 오니 아무 데나 건넌다","mis":"SO3-1-u1-X32"},{"t":"길에서 공놀이를 한다","mis":"SO3-1-u1-X32"},{"t":"신호를 보지 않는다","mis":"SO3-1-u1-X32"}],"explanation":["횡단보도","좌우 살피기","어린이도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#8','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',4,'essay','teacher','「우리 동네의 고칠 점」 가운데 하나를 골라 알맞은 방안을 쓰고, 내가 할 수 있는 실천을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u1-C12","difficulty":4,"kind":"essay","stem":"「우리 동네의 고칠 점」 가운데 하나를 골라 알맞은 방안을 쓰고, 내가 할 수 있는 실천을 쓰세요.","answer_guide":{"answer":"예: ㉢ 앉아서 쉴 곳이 없다 — 나무 그늘 아래 의자가 있는 작은 공원을 만들자고 마을에 의견을 낸다. 나는 공원이 생기면 쓰레기를 버리지 않고 깨끗하게 쓰겠다.","scoring_points":["문제를 골랐는가","문제에 맞는 방안을 썼는가","내가 할 실천을 썼는가"]},"explanation":["문제","방안","실천"],"asset":{"type":"passage","lines":["㉠ 놀이터 옆 길이 밤에 어둡다.","㉡ 버스 정류장 둘레에 쓰레기가 쌓여 있다.","㉢ 앉아서 쉴 곳이 없다.","㉣ 학교 앞에서 차가 빨리 달린다."],"title":"우리 동네의 고칠 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#9','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',4,'essay','teacher','우리 동네를 더 살기 좋게 만들기 위해 내가 바로 할 일 하나와 함께 할 일 하나를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u1-C12","difficulty":4,"kind":"essay","stem":"우리 동네를 더 살기 좋게 만들기 위해 내가 바로 할 일 하나와 함께 할 일 하나를 쓰세요.","answer_guide":{"answer":"예: 내가 바로 할 일 — 길에 쓰레기를 버리지 않고 이웃에게 먼저 인사한다. / 함께 할 일 — 어두운 골목에 가로등을 달자고 학급 회의에서 의견을 내고 의논한다.","scoring_points":["내가 바로 할 일을 썼는가","함께 할 일을 썼는가","실천할 수 있는 내용인가"]},"explanation":["나","함께","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_L12_challenge#10','soc',3,1,'u1','L12','g3_1_soc_u1_L12_challenge','lesson_challenge','SO3-1-u1-C12',4,'essay','teacher','학교 앞을 더 안전하게 만들기 위한 의견을 문제 · 까닭 · 방안이 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u1-C12","difficulty":4,"kind":"essay","stem":"학교 앞을 더 안전하게 만들기 위한 의견을 문제 · 까닭 · 방안이 드러나게 쓰세요.","answer_guide":{"answer":"예: 문제 — 학교 앞에서 차가 빨리 달린다. 까닭 — 어린이가 길을 건널 때 위험하다. 방안 — 어린이 보호구역 표지판을 더 크게 세우고, 등굣길에 천천히 운전해 달라는 안내를 한다.","scoring_points":["문제를 썼는가","까닭을 썼는가","알맞은 방안을 썼는가"]},"explanation":["문제","까닭","방안"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
