INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#10','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C2',2,'mc','auto','「하린이의 동네 탐험 일지」의 장소를 「누가 만들었나」로 나눌 때 바른 것은 무엇일까요?',ARRAY['SO3-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO3-1-u1-C2","difficulty":2,"kind":"mc","stem":"「하린이의 동네 탐험 일지」의 장소를 「누가 만들었나」로 나눌 때 바른 것은 무엇일까요?","options":[{"t":"자연: 뒷산 / 사람: 시장 · 도서관 · 보건소 · 수영장","correct":true},{"t":"자연: 뒷산 · 시장 / 사람: 도서관 · 보건소","mis":"SO3-1-u1-X03"},{"t":"자연: 도서관 / 사람: 뒷산 · 시장","mis":"SO3-1-u1-X03"},{"t":"모두 사람이 만든 곳","mis":"SO3-1-u1-X03"}],"explanation":["뒷산","나머지","누가 만들었나"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#11','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C3',2,'mc','auto','같은 보건소인데 하린이는 「무서웠어」, 민재는 「아프지 않아 다행이었어」라고 했어요. 바른 설명은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X01']::text[],false,'{"seq":11,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"mc","stem":"같은 보건소인데 하린이는 「무서웠어」, 민재는 「아프지 않아 다행이었어」라고 했어요. 바른 설명은 무엇일까요?","options":[{"t":"같은 장소라도 사람마다 느낌이 다를 수 있어요.","correct":true},{"t":"하린이가 잘못 느꼈어요.","mis":"SO3-1-u1-X09"},{"t":"민재가 잘못 느꼈어요.","mis":"SO3-1-u1-X09"},{"t":"보건소는 장소가 아니에요.","mis":"SO3-1-u1-X01"}],"explanation":["같은 장소","다른 느낌","모두 소중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#12','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C5',2,'mc','auto','하린이가 수영장 사진을 공유 앱에 올리려는데 사진에 다른 친구 얼굴이 나와요. 먼저 할 일은 무엇일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X15']::text[],false,'{"seq":12,"concept":"SO3-1-u1-C5","difficulty":2,"kind":"mc","stem":"하린이가 수영장 사진을 공유 앱에 올리려는데 사진에 다른 친구 얼굴이 나와요. 먼저 할 일은 무엇일까요?","options":[{"t":"그 친구에게 올려도 되는지 물어본다","correct":true},{"t":"그냥 올린다","mis":"SO3-1-u1-X16"},{"t":"친구 이름과 주소를 함께 적는다","mis":"SO3-1-u1-X16"},{"t":"얼굴에 낙서를 한다","mis":"SO3-1-u1-X15"}],"explanation":["친구 얼굴","허락","먼저"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
