INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#16','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C12',2,'mc','auto','「하린이의 동네 탐험 일지」 ⑥의 고칠 점에 알맞은 방안은 무엇일까요?',ARRAY['SO3-1-u1-X30','SO3-1-u1-X31']::text[],false,'{"seq":16,"concept":"SO3-1-u1-C12","difficulty":2,"kind":"mc","stem":"「하린이의 동네 탐험 일지」 ⑥의 고칠 점에 알맞은 방안은 무엇일까요?","options":[{"t":"쓰레기를 되가져가고 분리배출하자고 알린다","correct":true},{"t":"가로등을 단다","mis":"SO3-1-u1-X30"},{"t":"공원 의자를 없앤다","mis":"SO3-1-u1-X30"},{"t":"그냥 지나간다","mis":"SO3-1-u1-X31"}],"explanation":["⑥은","쓰레기","맞는 방안"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#17','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C2',3,'mc','auto','「하린이의 동네 탐험 일지」의 장소를 「하는 일」로 묶을 때 도서관과 같은 무리에 넣기 알맞은 곳은 어디일까요?',ARRAY['SO3-1-u1-X06','SO3-1-u1-X20','SO3-1-u1-X03']::text[],false,'{"seq":17,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"「하린이의 동네 탐험 일지」의 장소를 「하는 일」로 묶을 때 도서관과 같은 무리에 넣기 알맞은 곳은 어디일까요?","options":[{"t":"학교","correct":true},{"t":"시장","mis":"SO3-1-u1-X06"},{"t":"보건소","mis":"SO3-1-u1-X20"},{"t":"뒷산","mis":"SO3-1-u1-X03"}],"explanation":["도서관은","배움","학교도 배워요."],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#18','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C4',3,'mc','auto','하린이는 뒷산 약수터에서 맑은 공기를 마신 상쾌함을 친구들에게 생생하게 전하고 싶어요. 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X13']::text[],false,'{"seq":18,"concept":"SO3-1-u1-C4","difficulty":3,"kind":"mc","stem":"하린이는 뒷산 약수터에서 맑은 공기를 마신 상쾌함을 친구들에게 생생하게 전하고 싶어요. 가장 알맞은 것은 무엇일까요?","options":[{"t":"약수터 둘레 나무와 맑은 하늘을 그림으로 그려 느낌을 함께 소개한다","correct":true},{"t":"뒷산 이름만 말한다","mis":"SO3-1-u1-X12"},{"t":"친구 그림을 베껴 낸다","mis":"SO3-1-u1-X12"},{"t":"신문에 친구 비밀을 쓴다","mis":"SO3-1-u1-X13"}],"explanation":["모습","느낌","그림으로 소개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#19','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C7',3,'mc','auto','집 앞 골목에서 불이 난 것을 보았어요. 도움을 받으려면 어느 곳에 알려야 할까요?',ARRAY['SO3-1-u1-X18']::text[],false,'{"seq":19,"concept":"SO3-1-u1-C7","difficulty":3,"kind":"mc","stem":"집 앞 골목에서 불이 난 것을 보았어요. 도움을 받으려면 어느 곳에 알려야 할까요?","options":[{"t":"소방서","correct":true},{"t":"우체국","mis":"SO3-1-u1-X18"},{"t":"도서관","mis":"SO3-1-u1-X18"},{"t":"보건소","mis":"SO3-1-u1-X18"}],"explanation":["불","끄고 구해요.","소방서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#20','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C10',3,'mc','auto','하린이는 지금 도서관에 있어요. 수영장까지 가는 길을 찾으려면 어떻게 넣어야 할까요?',ARRAY['SO3-1-u1-X26']::text[],false,'{"seq":20,"concept":"SO3-1-u1-C10","difficulty":3,"kind":"mc","stem":"하린이는 지금 도서관에 있어요. 수영장까지 가는 길을 찾으려면 어떻게 넣어야 할까요?","options":[{"t":"출발: 도서관 · 도착: 수영장","correct":true},{"t":"출발: 수영장 · 도착: 도서관","mis":"SO3-1-u1-X26"},{"t":"출발: 집 · 도착: 도서관","mis":"SO3-1-u1-X26"},{"t":"출발: 도서관 · 도착: 도서관","mis":"SO3-1-u1-X26"}],"explanation":["지금 있는 곳","출발","도착은 수영장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#21','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C11',3,'mc','auto','우리 동네는 공원이 깨끗하고 병원도 가깝지만 밤길이 어두워요. 바르게 살펴본 것은 무엇일까요?',ARRAY['SO3-1-u1-X28','SO3-1-u1-X29']::text[],false,'{"seq":21,"concept":"SO3-1-u1-C11","difficulty":3,"kind":"mc","stem":"우리 동네는 공원이 깨끗하고 병원도 가깝지만 밤길이 어두워요. 바르게 살펴본 것은 무엇일까요?","options":[{"t":"환경 · 편리는 좋고, 안전은 고칠 점이에요.","correct":true},{"t":"모든 조건을 갖추었어요.","mis":"SO3-1-u1-X28"},{"t":"밤길은 어울림과 관련 있어요.","mis":"SO3-1-u1-X29"},{"t":"공원은 안전과 관련 있어요.","mis":"SO3-1-u1-X29"}],"explanation":["공원 = 환경","병원 = 편리","밤길 = 안전"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#22','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C1',3,'mc','auto','1단원에서 배운 것을 바르게 말한 친구는 누구일까요?',ARRAY['SO3-1-u1-X02','SO3-1-u1-X19','SO3-1-u1-X09']::text[],false,'{"seq":22,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"1단원에서 배운 것을 바르게 말한 친구는 누구일까요?","options":[{"t":"「장소마다 느낌이 다르고, 도움을 주는 장소가 우리 생활을 도와줘.」","correct":true},{"t":"「장소는 모두 같아.」","mis":"SO3-1-u1-X02"},{"t":"「도움을 주는 장소는 없어도 돼.」","mis":"SO3-1-u1-X19"},{"t":"「다른 느낌은 잘못이야.」","mis":"SO3-1-u1-X09"}],"explanation":["여러 장소와 느낌","도움 주는 장소","1단원"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#23','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C3',4,'essay','teacher','「하린이의 동네 탐험 일지」에서 장소 하나를 골라 장소 카드(장소 이름 · 경험 · 느낌)를 쓰세요. 느낌이 쓰여 있지 않으면 내가 짐작해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u1-C3","difficulty":4,"kind":"essay","stem":"「하린이의 동네 탐험 일지」에서 장소 하나를 골라 장소 카드(장소 이름 · 경험 · 느낌)를 쓰세요. 느낌이 쓰여 있지 않으면 내가 짐작해 쓰세요.","answer_guide":{"answer":"예: 장소 — 도서관 / 경험 — 곤충 책을 빌렸다 / 느낌 — 좋아하는 곤충 사진이 많아 설레었다.","scoring_points":["장소 이름을 썼는가","경험을 썼는가","느낌을 썼는가"]},"explanation":["장소","경험","느낌"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#24','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C8',4,'essay','teacher','도움을 주는 장소 네 곳을 하는 일에 따라 무리지어 쓰고, 각 무리의 이름을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u1-C8","difficulty":4,"kind":"essay","stem":"도움을 주는 장소 네 곳을 하는 일에 따라 무리지어 쓰고, 각 무리의 이름을 쓰세요.","answer_guide":{"answer":"예: 안전을 지키는 곳 — 소방서 · 경찰서 / 건강을 돌보는 곳 — 병원 · 보건소","scoring_points":["네 곳을 썼는가","하는 일에 맞게 묶었는가","무리 이름을 썼는가"]},"explanation":["하는 일","묶기","이름"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_a#25','soc',3,1,'u1','','g3_1_soc_u1_review_a','unit_review','SO3-1-u1-C12',4,'essay','teacher','「하린이의 동네 탐험 일지」 ⑥의 고칠 점에 알맞은 방안을 쓰고, 하린이가 바로 할 수 있는 실천을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u1-C12","difficulty":4,"kind":"essay","stem":"「하린이의 동네 탐험 일지」 ⑥의 고칠 점에 알맞은 방안을 쓰고, 하린이가 바로 할 수 있는 실천을 쓰세요.","answer_guide":{"answer":"예: 방안 — 수영장 가는 길에 쓰레기통을 두고 쓰레기를 되가져가자는 안내문을 붙이자고 마을에 의견을 낸다. / 실천 — 하린이부터 쓰레기를 버리지 않고 가방에 넣어 집에 가져간다.","scoring_points":["고칠 점에 맞는 방안을 썼는가","하린이가 할 실천을 썼는가","실천할 수 있는 내용인가"]},"explanation":["⑥","방안","실천"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
