INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#11','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C3',2,'mc','auto','친구가 「나는 시장이 너무 시끄러워서 싫어.」라고 했어요. 존중하는 대답은 무엇일까요?',ARRAY['SO3-1-u1-X11','SO3-1-u1-X09']::text[],false,'{"seq":11,"concept":"SO3-1-u1-C3","difficulty":2,"kind":"mc","stem":"친구가 「나는 시장이 너무 시끄러워서 싫어.」라고 했어요. 존중하는 대답은 무엇일까요?","options":[{"t":"「그랬구나. 나는 시장이 북적여서 재미있는데, 서로 느낌이 다르네.」","correct":true},{"t":"「시장이 싫다니 이상해.」","mis":"SO3-1-u1-X11"},{"t":"「그건 잘못 느낀 거야.」","mis":"SO3-1-u1-X09"},{"t":"「네 말은 안 들을래.」","mis":"SO3-1-u1-X11"}],"explanation":["다른 느낌","내 느낌도","함께 존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#12','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C5',2,'mc','auto','다음 댓글 가운데 고운 말로 바꿔야 할 것은 무엇일까요?',ARRAY['SO3-1-u1-X15']::text[],false,'{"seq":12,"concept":"SO3-1-u1-C5","difficulty":2,"kind":"mc","stem":"다음 댓글 가운데 고운 말로 바꿔야 할 것은 무엇일까요?","options":[{"t":"「이것도 그림이라고 그렸냐?」","correct":true},{"t":"「색깔이 참 따뜻해 보여.」","mis":"SO3-1-u1-X15"},{"t":"「어디를 그렸는지 궁금해!」","mis":"SO3-1-u1-X15"},{"t":"「다음 그림도 기대할게.」","mis":"SO3-1-u1-X15"}],"explanation":["흉보는 말","찾아요.","고운 말로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
