INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#14','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C10',2,'mc','auto','집에서 수영장까지 길찾기를 할 때 바르게 넣은 것은 무엇일까요?',ARRAY['SO3-1-u1-X26']::text[],false,'{"seq":14,"concept":"SO3-1-u1-C10","difficulty":2,"kind":"mc","stem":"집에서 수영장까지 길찾기를 할 때 바르게 넣은 것은 무엇일까요?","options":[{"t":"출발: 집 · 도착: 수영장","correct":true},{"t":"출발: 수영장 · 도착: 집","mis":"SO3-1-u1-X26"},{"t":"출발: 수영장 · 도착: 수영장","mis":"SO3-1-u1-X26"},{"t":"출발만 넣고 도착은 비운다","mis":"SO3-1-u1-X26"}],"explanation":["지금 있는 곳","가려는 곳","집 → 수영장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#15','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C11',2,'mc','auto','「하린이의 동네 탐험 일지」 ⑦은 살기 좋은 곳의 어떤 조건이 드러난 일일까요?',ARRAY['SO3-1-u1-X29']::text[],false,'{"seq":15,"concept":"SO3-1-u1-C11","difficulty":2,"kind":"mc","stem":"「하린이의 동네 탐험 일지」 ⑦은 살기 좋은 곳의 어떤 조건이 드러난 일일까요?","options":[{"t":"어울림","correct":true},{"t":"안전","mis":"SO3-1-u1-X29"},{"t":"편리","mis":"SO3-1-u1-X29"},{"t":"환경","mis":"SO3-1-u1-X29"}],"explanation":["⑦을 봐요.","이웃","어울림"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#16','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C12',2,'mc','auto','동네를 함께 바꾸고 싶을 때 알맞은 방법은 무엇일까요?',ARRAY['SO3-1-u1-X31']::text[],false,'{"seq":16,"concept":"SO3-1-u1-C12","difficulty":2,"kind":"mc","stem":"동네를 함께 바꾸고 싶을 때 알맞은 방법은 무엇일까요?","options":[{"t":"학급 회의나 마을에 의견을 내고 함께 의논한다","correct":true},{"t":"혼자 불평만 한다","mis":"SO3-1-u1-X31"},{"t":"아무에게도 말하지 않는다","mis":"SO3-1-u1-X31"},{"t":"친구 탓을 한다","mis":"SO3-1-u1-X31"}],"explanation":["의견","의논","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#17','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C1',3,'mc','auto','하린이는 「뒷산은 아무도 만들지 않았으니 장소가 아니야.」라고 했어요. 알맞게 고친 말은 무엇일까요?',ARRAY['SO3-1-u1-X03','SO3-1-u1-X01']::text[],false,'{"seq":17,"concept":"SO3-1-u1-C1","difficulty":3,"kind":"mc","stem":"하린이는 「뒷산은 아무도 만들지 않았으니 장소가 아니야.」라고 했어요. 알맞게 고친 말은 무엇일까요?","options":[{"t":"「뒷산은 자연이 만든 곳이고, 우리가 찾아가는 장소야.」","correct":true},{"t":"「맞아, 장소가 아니야.」","mis":"SO3-1-u1-X03"},{"t":"「뒷산은 사람이 만든 곳이야.」","mis":"SO3-1-u1-X03"},{"t":"「장소는 갈 수 없는 곳이야.」","mis":"SO3-1-u1-X01"}],"explanation":["누가 만들었나","자연","그래도 장소"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#18','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C3',3,'mc','auto','「하린이의 동네 탐험 일지」 ④로 장소 카드를 만들 때 바른 것은 무엇일까요?',ARRAY['SO3-1-u1-X08','SO3-1-u1-X10']::text[],false,'{"seq":18,"concept":"SO3-1-u1-C3","difficulty":3,"kind":"mc","stem":"「하린이의 동네 탐험 일지」 ④로 장소 카드를 만들 때 바른 것은 무엇일까요?","options":[{"t":"보건소 — 예방 주사를 맞았다 — 조금 무서웠다","correct":true},{"t":"보건소 — 조금 무서웠다 — 예방 주사를 맞았다","mis":"SO3-1-u1-X08"},{"t":"보건소 — 키를 쟀다 — 140 cm","mis":"SO3-1-u1-X10"},{"t":"예방 주사 — 보건소 — 무서웠다","mis":"SO3-1-u1-X08"}],"explanation":["장소","경험","느낌"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#19','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C7',3,'mc','auto','「병원은 아플 때 나 혼자만 가는 곳이야.」를 바르게 고친 것은 무엇일까요?',ARRAY['SO3-1-u1-X18','SO3-1-u1-X19','SO3-1-u1-X17']::text[],false,'{"seq":19,"concept":"SO3-1-u1-C7","difficulty":3,"kind":"mc","stem":"「병원은 아플 때 나 혼자만 가는 곳이야.」를 바르게 고친 것은 무엇일까요?","options":[{"t":"「병원은 여러 사람이 함께 이용하며 건강을 돌봐 주는 곳이야.」","correct":true},{"t":"「병원은 불을 끄는 곳이야.」","mis":"SO3-1-u1-X18"},{"t":"「병원은 없어도 돼.」","mis":"SO3-1-u1-X19"},{"t":"「병원은 우리 집 안에 있어.」","mis":"SO3-1-u1-X17"}],"explanation":["나만?","여러 사람","건강"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#20','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C9',3,'mc','auto','보건소를 처음 찾아가는 하린이에게 가장 알맞은 지도 사용 순서는 무엇일까요?',ARRAY['SO3-1-u1-X24','SO3-1-u1-X25','SO3-1-u1-X26']::text[],false,'{"seq":20,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"보건소를 처음 찾아가는 하린이에게 가장 알맞은 지도 사용 순서는 무엇일까요?","options":[{"t":"「보건소」 검색 → 위치 확인 → 길찾기로 가는 길 확인","correct":true},{"t":"지도 끄기 → 짐작해서 가기","mis":"SO3-1-u1-X24"},{"t":"－만 계속 누르기","mis":"SO3-1-u1-X25"},{"t":"위성 보기만 켜기","mis":"SO3-1-u1-X26"}],"explanation":["검색","위치","길찾기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#21','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C11',3,'mc','auto','「어울림」 조건을 갖추기 위한 실천으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X29','SO3-1-u1-X28','SO3-1-u1-X27']::text[],false,'{"seq":21,"concept":"SO3-1-u1-C11","difficulty":3,"kind":"mc","stem":"「어울림」 조건을 갖추기 위한 실천으로 알맞은 것은 무엇일까요?","options":[{"t":"이웃과 함께 마을 청소에 참여하고 인사를 나눈다","correct":true},{"t":"밤에 가로등을 끈다","mis":"SO3-1-u1-X29"},{"t":"큰 가게를 더 짓는다","mis":"SO3-1-u1-X28"},{"t":"쓰레기를 길에 버린다","mis":"SO3-1-u1-X27"}],"explanation":["어울림","이웃","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#22','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C12',3,'mc','auto','1단원의 두 묶음을 바르게 고른 것은 무엇일까요?',ARRAY['SO3-1-u1-X01','SO3-1-u1-X12']::text[],false,'{"seq":22,"concept":"SO3-1-u1-C12","difficulty":3,"kind":"mc","stem":"1단원의 두 묶음을 바르게 고른 것은 무엇일까요?","options":[{"t":"여러 장소와 느낌의 존중 · 도움을 주는 장소와 더 살기 좋은 곳","correct":true},{"t":"분수와 그래프 · 덧셈과 뺄셈","mis":"SO3-1-u1-X01"},{"t":"날씨와 계절 · 동물과 식물","mis":"SO3-1-u1-X01"},{"t":"노래와 춤 · 그림과 만들기","mis":"SO3-1-u1-X12"}],"explanation":["①","②","두 묶음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#23','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C2',4,'essay','teacher','「하린이의 동네 탐험 일지」의 장소들을 내가 정한 기준으로 두 무리로 나누고 기준을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u1-C2","difficulty":4,"kind":"essay","stem":"「하린이의 동네 탐험 일지」의 장소들을 내가 정한 기준으로 두 무리로 나누고 기준을 쓰세요.","answer_guide":{"answer":"예: 기준 — 누가 만들었나 / 자연이 만든 곳: 뒷산 / 사람이 만든 곳: 시장 · 도서관 · 보건소 · 수영장 · 공원","scoring_points":["기준을 썼는가","두 무리로 나누었는가","기준에 맞게 나누었는가"]},"explanation":["기준","두 무리","빠짐없이"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#24','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C7',4,'essay','teacher','우리 동네에 도움을 주는 장소가 하나도 없다면 어떤 점이 불편할지 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u1-C7","difficulty":4,"kind":"essay","stem":"우리 동네에 도움을 주는 장소가 하나도 없다면 어떤 점이 불편할지 두 가지 쓰세요.","answer_guide":{"answer":"예: 아플 때 가까운 병원이 없어 치료를 받기 어렵다. 불이 났을 때 소방서가 없어 빨리 불을 끄기 어렵다.","scoring_points":["불편한 점 두 가지를 썼는가","장소가 주는 도움과 이어 썼는가","내용이 알맞은가"]},"explanation":["병원이 없다면","소방서가 없다면","불편"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_b#25','soc',3,1,'u1','','g3_1_soc_u1_review_b','unit_review','SO3-1-u1-C11',4,'essay','teacher','우리 동네를 살기 좋은 곳의 네 가지 조건 가운데 두 가지로 살펴보고, 좋은 점이나 고칠 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u1-C11","difficulty":4,"kind":"essay","stem":"우리 동네를 살기 좋은 곳의 네 가지 조건 가운데 두 가지로 살펴보고, 좋은 점이나 고칠 점을 쓰세요.","answer_guide":{"answer":"예: 편리 — 집 가까이에 도서관과 병원이 있어 좋다. / 안전 — 학교 앞 횡단보도에 신호등이 없어 고쳐야 한다.","scoring_points":["조건 두 가지를 골랐는가","조건에 맞게 살펴보았는가","좋은 점이나 고칠 점을 썼는가"]},"explanation":["조건","살펴보기","좋은 점 · 고칠 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#1','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C1',1,'mc','auto','「하린이의 동네 탐험 일지」에서 하린이가 책을 빌린 장소는 어디일까요?',ARRAY['SO3-1-u1-X04']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C1","difficulty":1,"kind":"mc","stem":"「하린이의 동네 탐험 일지」에서 하린이가 책을 빌린 장소는 어디일까요?","options":[{"t":"도서관","correct":true},{"t":"시장","mis":"SO3-1-u1-X04"},{"t":"보건소","mis":"SO3-1-u1-X04"},{"t":"수영장","mis":"SO3-1-u1-X04"}],"explanation":["③을 봐요.","책","도서관"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
