INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#17','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C2',3,'mc','auto','「자주 가는 곳」 기준으로 나눈 친구와 내 무리가 달라요. 바른 생각은 무엇일까요?',ARRAY['SO3-1-u1-X07','SO3-1-u1-X05']::text[],false,'{"seq":17,"concept":"SO3-1-u1-C2","difficulty":3,"kind":"mc","stem":"「자주 가는 곳」 기준으로 나눈 친구와 내 무리가 달라요. 바른 생각은 무엇일까요?","options":[{"t":"사람마다 생활이 달라 자주 가는 곳도 다르므로 무리가 다를 수 있다","correct":true},{"t":"내 무리가 맞고 친구가 잘못이다","mis":"SO3-1-u1-X07"},{"t":"기준은 늘 같아야 한다","mis":"SO3-1-u1-X07"},{"t":"이런 기준으로는 나눌 수 없다","mis":"SO3-1-u1-X05"}],"explanation":["자주 가는 곳","사람마다","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#18','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C5',3,'mc','auto','하린이가 장소 카드를 공유 앱에 올리려 해요. 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X16','SO3-1-u1-X15']::text[],false,'{"seq":18,"concept":"SO3-1-u1-C5","difficulty":3,"kind":"mc","stem":"하린이가 장소 카드를 공유 앱에 올리려 해요. 알맞은 것은 무엇일까요?","options":[{"t":"카드를 사진으로 찍어 올리고, 친구 정보는 넣지 않는다","correct":true},{"t":"카드에 내 전화번호도 적어 올린다","mis":"SO3-1-u1-X16"},{"t":"친구 얼굴 사진을 허락 없이 붙인다","mis":"SO3-1-u1-X16"},{"t":"친구 카드를 흉보는 글과 함께 올린다","mis":"SO3-1-u1-X15"}],"explanation":["사진","올리기","정보 지키기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#19','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C8',3,'mc','auto','은행 · 우체국을 「생활을 편리하게 돕는 곳」으로 묶었어요. 이 무리에 더 넣기 알맞은 곳은 어디일까요?',ARRAY['SO3-1-u1-X20']::text[],false,'{"seq":19,"concept":"SO3-1-u1-C8","difficulty":3,"kind":"mc","stem":"은행 · 우체국을 「생활을 편리하게 돕는 곳」으로 묶었어요. 이 무리에 더 넣기 알맞은 곳은 어디일까요?","options":[{"t":"버스 정류장","correct":true},{"t":"소방서","mis":"SO3-1-u1-X20"},{"t":"병원","mis":"SO3-1-u1-X20"},{"t":"보건소","mis":"SO3-1-u1-X20"}],"explanation":["생활을","편리하게","버스 정류장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#20','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C10',3,'mc','auto','보건소 건물 입구가 어디인지 사진처럼 보고 싶어요. 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X25','SO3-1-u1-X26','SO3-1-u1-X24']::text[],false,'{"seq":20,"concept":"SO3-1-u1-C10","difficulty":3,"kind":"mc","stem":"보건소 건물 입구가 어디인지 사진처럼 보고 싶어요. 알맞은 것은 무엇일까요?","options":[{"t":"위성 보기로 바꾸고 ＋로 확대한다","correct":true},{"t":"－로 축소만 한다","mis":"SO3-1-u1-X25"},{"t":"길찾기만 누른다","mis":"SO3-1-u1-X26"},{"t":"화면을 끌기만 한다","mis":"SO3-1-u1-X24"}],"explanation":["사진처럼","크게","위성 보기 · 확대"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#21','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C12',3,'mc','auto','「바람마을 소식」처럼 살기 좋은 마을이 되려면 우리 동네의 어두운 골목에 필요한 방안은 무엇일까요?',ARRAY['SO3-1-u1-X30','SO3-1-u1-X31']::text[],false,'{"seq":21,"concept":"SO3-1-u1-C12","difficulty":3,"kind":"mc","stem":"「바람마을 소식」처럼 살기 좋은 마을이 되려면 우리 동네의 어두운 골목에 필요한 방안은 무엇일까요?","options":[{"t":"가로등을 달자고 마을에 의견을 낸다","correct":true},{"t":"공원을 없앤다","mis":"SO3-1-u1-X30"},{"t":"그냥 참는다","mis":"SO3-1-u1-X31"},{"t":"쓰레기통을 치운다","mis":"SO3-1-u1-X30"}],"explanation":["어두운 골목","안전","가로등"],"asset":{"type":"passage","lines":["① 밤에도 골목마다 가로등이 환하다.","② 마을 가운데 공원에 나무가 많고 깨끗하다.","③ 걸어서 가까운 곳에 병원과 도서관이 있다.","④ 이웃들이 아침마다 서로 인사한다."],"title":"바람마을 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#22','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C9',3,'mc','auto','하린이가 동네 탐험에서 배운 것을 모두 활용한 것은 무엇일까요?',ARRAY['SO3-1-u1-X24','SO3-1-u1-X10','SO3-1-u1-X31']::text[],false,'{"seq":22,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"하린이가 동네 탐험에서 배운 것을 모두 활용한 것은 무엇일까요?","options":[{"t":"지도로 장소를 찾고, 느낌을 그림일기에 담고, 고칠 점의 방안을 생각했다","correct":true},{"t":"지도 없이 짐작으로만 다녔다","mis":"SO3-1-u1-X24"},{"t":"느낌은 쓰지 않고 장소 이름만 적었다","mis":"SO3-1-u1-X10"},{"t":"고칠 점을 보고도 못 본 척했다","mis":"SO3-1-u1-X31"}],"explanation":["지도","느낌","방안"],"asset":{"type":"passage","lines":["① 아침에 뒷산 약수터에 올라 맑은 공기를 마셨다.","② 시장에서 엄마와 떡을 사고 떡집 할머니께 인사했다.","③ 도서관에서 곤충 책을 빌렸다.","④ 보건소에서 예방 주사를 맞았는데 조금 무서웠다.","⑤ 지도 앱으로 수영장 가는 길을 찾았다.","⑥ 수영장 가는 길에 쓰레기가 쌓인 곳이 있었다.","⑦ 저녁에 공원 의자에 앉아 이웃 할아버지와 이야기했다."],"title":"하린이의 동네 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#23','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C3',4,'essay','teacher','같은 장소에 대해 친구와 내 느낌이 달랐던 경험을 쓰고, 그때 어떻게 하면 좋은지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u1-C3","difficulty":4,"kind":"essay","stem":"같은 장소에 대해 친구와 내 느낌이 달랐던 경험을 쓰고, 그때 어떻게 하면 좋은지 쓰세요.","answer_guide":{"answer":"예: 놀이공원에서 나는 롤러코스터가 신났지만 동생은 무서워했다. 이럴 때는 동생의 느낌을 놀리지 않고 존중하며 다른 놀이 기구를 함께 탄다.","scoring_points":["경험을 썼는가","느낌이 달랐던 점을 썼는가","존중하는 태도를 썼는가"]},"explanation":["같은 장소","다른 느낌","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#24','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C10',4,'essay','teacher','하린이가 집에서 보건소까지 처음 가는 길을 디지털 영상 지도로 찾는 방법을 차례대로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u1-C10","difficulty":4,"kind":"essay","stem":"하린이가 집에서 보건소까지 처음 가는 길을 디지털 영상 지도로 찾는 방법을 차례대로 쓰세요.","answer_guide":{"answer":"예: 검색창에 보건소를 입력해 위치를 찾는다. ＋와 －로 크기를 맞추어 둘레를 살핀다. 길찾기에서 출발은 집, 도착은 보건소로 넣어 가는 길을 확인한다.","scoring_points":["검색을 썼는가","길찾기 출발 · 도착을 바르게 썼는가","차례가 알맞은가"]},"explanation":["검색","크기 맞추기","길찾기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_c#25','soc',3,1,'u1','','g3_1_soc_u1_review_c','unit_review','SO3-1-u1-C12',4,'essay','teacher','우리 동네를 더 살기 좋게 만들기 위해 학급 회의에 낼 의견을 문제 · 까닭 · 방안으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u1-C12","difficulty":4,"kind":"essay","stem":"우리 동네를 더 살기 좋게 만들기 위해 학급 회의에 낼 의견을 문제 · 까닭 · 방안으로 쓰세요.","answer_guide":{"answer":"예: 문제 — 공원에 앉을 의자가 없다. 까닭 — 할머니 할아버지들이 쉬기 어렵다. 방안 — 공원 나무 그늘 아래에 의자를 놓아 달라고 마을에 건의한다.","scoring_points":["문제를 썼는가","까닭을 썼는가","알맞은 방안을 썼는가"]},"explanation":["문제","까닭","방안"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#1','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C1',1,'mc','auto','다음 가운데 찾아갈 수 있는 장소가 아닌 것은 무엇일까요?',ARRAY['SO3-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO3-1-u1-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 찾아갈 수 있는 장소가 아닌 것은 무엇일까요?","options":[{"t":"내일","correct":true},{"t":"공원","mis":"SO3-1-u1-X01"},{"t":"시장","mis":"SO3-1-u1-X01"},{"t":"냇물","mis":"SO3-1-u1-X01"}],"explanation":["갈 수 있나요?","내일은 때","장소가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#2','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C2',1,'mc','auto','「하는 일」 기준으로 시장은 어느 무리일까요?',ARRAY['SO3-1-u1-X04','SO3-1-u1-X06']::text[],false,'{"seq":2,"concept":"SO3-1-u1-C2","difficulty":1,"kind":"mc","stem":"「하는 일」 기준으로 시장은 어느 무리일까요?","options":[{"t":"사고파는 곳","correct":true},{"t":"배우는 곳","mis":"SO3-1-u1-X04"},{"t":"노는 곳","mis":"SO3-1-u1-X04"},{"t":"자연이 만든 곳","mis":"SO3-1-u1-X06"}],"explanation":["시장에서는","사고팔아요.","사고파는 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
