INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#15','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C11',2,'mc','auto','살기 좋은 곳의 조건을 가장 많이 갖춘 마을은 어디일까요?',ARRAY['SO3-1-u1-X28','SO3-1-u1-X27','SO3-1-u1-X29']::text[],false,'{"seq":15,"concept":"SO3-1-u1-C11","difficulty":2,"kind":"mc","stem":"살기 좋은 곳의 조건을 가장 많이 갖춘 마을은 어디일까요?","options":[{"t":"길이 밝고, 공원이 깨끗하고, 병원이 가깝고, 이웃이 서로 돕는 마을","correct":true},{"t":"가게는 많지만 길이 어두운 마을","mis":"SO3-1-u1-X28"},{"t":"공원은 있지만 쓰레기가 가득한 마을","mis":"SO3-1-u1-X27"},{"t":"병원은 가깝지만 이웃끼리 다투는 마을","mis":"SO3-1-u1-X29"}],"explanation":["안전 · 환경","편리 · 어울림","모두"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
