INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#17','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C8',3,'mc','auto','「경찰서 · 도서관 · 병원」을 「안전을 지키는 곳」 한 무리로 묶었어요. 바르게 고친 것은 무엇일까요?',ARRAY['SO3-1-u1-X20','SO3-1-u1-X05']::text[],false,'{"seq":17,"concept":"SO3-1-u1-C8","difficulty":3,"kind":"mc","stem":"「경찰서 · 도서관 · 병원」을 「안전을 지키는 곳」 한 무리로 묶었어요. 바르게 고친 것은 무엇일까요?","options":[{"t":"안전: 경찰서 / 배움: 도서관 / 건강: 병원","correct":true},{"t":"그대로 둔다","mis":"SO3-1-u1-X20"},{"t":"안전: 도서관 / 건강: 경찰서 · 병원","mis":"SO3-1-u1-X20"},{"t":"무리를 없앤다","mis":"SO3-1-u1-X05"}],"explanation":["하는 일이","다르면","다른 무리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#18','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C6',3,'mc','auto','그림일기와 마을 신문의 다른 점으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X12','SO3-1-u1-X16','SO3-1-u1-X13']::text[],false,'{"seq":18,"concept":"SO3-1-u1-C6","difficulty":3,"kind":"mc","stem":"그림일기와 마을 신문의 다른 점으로 알맞은 것은 무엇일까요?","options":[{"t":"그림일기는 내 경험과 느낌을, 마을 신문은 여러 장소의 모습과 소식을 담아요.","correct":true},{"t":"둘 다 아무것도 담지 않아요.","mis":"SO3-1-u1-X12"},{"t":"그림일기에는 친구 주소를 담아요.","mis":"SO3-1-u1-X16"},{"t":"마을 신문에는 친구 비밀을 담아요.","mis":"SO3-1-u1-X13"}],"explanation":["그림일기","마을 신문","담는 것"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#19','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C7',3,'mc','auto','도움을 주는 장소를 이용하는 바른 모습은 무엇일까요?',ARRAY['SO3-1-u1-X17','SO3-1-u1-X19']::text[],false,'{"seq":19,"concept":"SO3-1-u1-C7","difficulty":3,"kind":"mc","stem":"도움을 주는 장소를 이용하는 바른 모습은 무엇일까요?","options":[{"t":"보건소에서 차례를 기다리며 조용히 한다","correct":true},{"t":"도서관 책에 낙서한다","mis":"SO3-1-u1-X17"},{"t":"경찰서에 장난 전화를 건다","mis":"SO3-1-u1-X19"},{"t":"우체국에서 새치기한다","mis":"SO3-1-u1-X17"}],"explanation":["함께 쓰는 곳","차례","예절"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#20','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C9',3,'mc','auto','디지털 영상 지도에 대해 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u1-X22','SO3-1-u1-X23','SO3-1-u1-X24']::text[],false,'{"seq":20,"concept":"SO3-1-u1-C9","difficulty":3,"kind":"mc","stem":"디지털 영상 지도에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"위성 · 항공 사진으로 실제 모습을 보여 주고, 검색하면 장소를 쉽게 찾는다","correct":true},{"t":"손으로 상상해 그린 그림이다","mis":"SO3-1-u1-X22"},{"t":"장소의 냄새까지 알려 준다","mis":"SO3-1-u1-X23"},{"t":"이름을 알아도 검색할 수 없다","mis":"SO3-1-u1-X24"}],"explanation":["사진","실제 모습","검색"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#21','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C11',3,'mc','auto','살기 좋은 곳을 생각하는 마음으로 가장 알맞은 말은 무엇일까요?',ARRAY['SO3-1-u1-X28','SO3-1-u1-X27']::text[],false,'{"seq":21,"concept":"SO3-1-u1-C11","difficulty":3,"kind":"mc","stem":"살기 좋은 곳을 생각하는 마음으로 가장 알맞은 말은 무엇일까요?","options":[{"t":"「나만이 아니라 이웃 모두가 안전하고 편리하고 사이좋게 지낼 수 있어야 해.」","correct":true},{"t":"「나만 편하면 돼.」","mis":"SO3-1-u1-X28"},{"t":"「가게만 많으면 돼.」","mis":"SO3-1-u1-X28"},{"t":"「쓰레기는 상관없어.」","mis":"SO3-1-u1-X27"}],"explanation":["모두","여러 조건","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#22','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C3',3,'mc','auto','단원을 마치며 다짐한 말로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u1-X09','SO3-1-u1-X31','SO3-1-u1-X15']::text[],false,'{"seq":22,"concept":"SO3-1-u1-C3","difficulty":3,"kind":"mc","stem":"단원을 마치며 다짐한 말로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「친구의 다른 느낌을 존중하고, 우리 동네를 위해 작은 실천을 할래.」","correct":true},{"t":"「내 느낌만 맞다고 할래.」","mis":"SO3-1-u1-X09"},{"t":"「동네 일은 어른들이 할 거야.」","mis":"SO3-1-u1-X31"},{"t":"「공유 앱에선 아무 말이나 할래.」","mis":"SO3-1-u1-X15"}],"explanation":["존중","실천","다짐"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#23','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C5',4,'essay','teacher','우리 동네 장소를 표현한 작품을 공유 앱에 올릴 때 쓸 설명과, 친구 작품에 달 고운 댓글을 하나씩 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u1-C5","difficulty":4,"kind":"essay","stem":"우리 동네 장소를 표현한 작품을 공유 앱에 올릴 때 쓸 설명과, 친구 작품에 달 고운 댓글을 하나씩 쓰세요.","answer_guide":{"answer":"예: 설명 — 「동네 뒷산 약수터 그림이에요. 아침 공기가 맑아 상쾌했던 마음을 초록색으로 그렸어요.」 / 댓글 — 「시장 그림 속 사람들이 북적여서 정말 활기차 보여!」","scoring_points":["장소 · 경험 · 느낌을 담은 설명을 썼는가","고운 댓글을 썼는가","남의 정보를 넣지 않았는가"]},"explanation":["설명","댓글","고운 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#24','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C9',4,'essay','teacher','디지털 영상 지도로 알 수 있는 것 두 가지와 알 수 없는 것 한 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u1-C9","difficulty":4,"kind":"essay","stem":"디지털 영상 지도로 알 수 있는 것 두 가지와 알 수 없는 것 한 가지를 쓰세요.","answer_guide":{"answer":"예: 알 수 있는 것 — 장소의 위치, 그곳까지 가는 길 / 알 수 없는 것 — 그 장소에서 나는 냄새","scoring_points":["알 수 있는 것 두 가지를 썼는가","알 수 없는 것을 썼는가","내용이 바른가"]},"explanation":["위치","가는 길","냄새는?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u1_review_d#25','soc',3,1,'u1','','g3_1_soc_u1_review_d','unit_review','SO3-1-u1-C1',4,'essay','teacher','1단원 「우리가 사는 곳」에서 배운 것 가운데 가장 기억에 남는 것 두 가지를 쓰고, 앞으로 생활에서 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u1-C1","difficulty":4,"kind":"essay","stem":"1단원 「우리가 사는 곳」에서 배운 것 가운데 가장 기억에 남는 것 두 가지를 쓰고, 앞으로 생활에서 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 같은 장소라도 사람마다 느낌이 다르다는 것과 디지털 영상 지도로 장소를 찾는 방법이 기억에 남는다. 앞으로 친구의 다른 느낌을 존중하고, 처음 가는 곳은 지도로 길을 찾아보겠다.","scoring_points":["배운 것 두 가지를 썼는가","내용이 바른가","생활에서의 쓰임을 썼는가"]},"explanation":["기억에 남는 것","두 가지","생활 속으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
